function baseTenantProfile(){return tenantProfiles['P.302']||{rent:0,deposit:0,startDate:'',term:'',dueDay:'Ngày 05 hằng tháng',dueDate:'',dueStatus:'',dueNote:'',dueAmount:0,contractStatus:'Chưa lập',contract:'',assets:[],repairs:[],payments:[],invoices:[],documents:[]}}
function readHandoverRecords(){try{return JSON.parse(localStorage.getItem('homeInventoryRecords')||'[]').filter(record=>record&&typeof record==='object')}catch{return []}}
function getConfirmedRoomHandover(room){return readHandoverRecords().filter(record=>record.room===room&&record.type==='Giao phòng'&&record.status==='Đã được khách thuê xác nhận').sort((a,b)=>b.time-a.time)[0]||null}
function openHandoverReview(id){const record=readHandoverRecords().find(item=>String(item.id)===String(id));if(!record)return;const photos=(record.photos||[]).map((photo,index)=>`<img src="${photo}" alt="Ảnh bàn giao ${index+1}" style="width:100%;max-height:190px;object-fit:cover;border-radius:12px;margin-top:8px">`).join(''),utilityReadingSummary=Object.entries(record.utilityReadings||{}).map(([service,value])=>(service==='electricity'?'Điện':'Nước')+' đầu kỳ: '+value+' '+(service==='electricity'?'kWh':'m³')).join(' · ');const items=(record.items||[]).map(item=>`<div class="tenant-asset"><span>${escapeHTML(item.name)} ×${Number(item.actual)||0}<small style="display:block;color:#6f746f;margin-top:3px">Mốc ${Number(item.expected)||0} · ${escapeHTML(item.condition||'Chưa ghi')}${item.note?' · '+escapeHTML(item.note):''}</small>${item.photo?`<img src="${item.photo}" alt="Ảnh ${escapeHTML(item.name)}" style="display:block;width:100%;max-height:130px;object-fit:cover;border-radius:9px;margin-top:7px">`:''}</span><strong>${Number(item.actual)===Number(item.expected)?'Đã đối chiếu':'Lệch mốc'}</strong></div>`).join('');const pending=record.status!=='Đã được khách thuê xác nhận',account=document.getElementById('accountSelect').value.split('|'),pop=document.createElement('div');pop.className='modal-overlay';pop.innerHTML=`<div class="modal-sheet"><div class="modal-head">Biên bản bàn giao · ${escapeHTML(record.room)}</div><div class="tenant-kv"><span>Người quản lý</span><strong>${escapeHTML(record.inspector||'')}</strong></div><div class="tenant-kv"><span>Người thuê</span><strong>${escapeHTML(record.tenant||'')}</strong></div><div class="tenant-kv"><span>Ngày lập</span><strong>${new Date(record.time).toLocaleString('vi-VN')}</strong></div><div class="report"><h3>Tài sản đã kiểm tra</h3>${items||'<div class="note">Không có tài sản trong biên bản.</div>'}</div><div class="report"><h3>Chỉ số và ghi chú bàn giao</h3><div class="handover-notes">${utilityReadingSummary?`<strong>${escapeHTML(utilityReadingSummary)}</strong><br>`:''}${escapeHTML(record.notes||'Không có ghi chú')}${record.tenantNote?`<br><strong>Khách yêu cầu kiểm tra:</strong> ${escapeHTML(record.tenantNote)}`:''}</div></div>${photos?`<div class="report"><h3>Ảnh hiện trạng</h3>${photos}</div>`:''}${pending&&account[0]==='tenant'&&account[2]===record.room?`<label>Họ tên xác nhận nhận phòng</label><input id="handoverSignatureName" value="${escapeHTML(account[1])}" required><label style="display:flex;gap:8px;align-items:center"><input id="handoverAgree" type="checkbox" style="width:auto"> Tôi đã cùng kiểm tra và xác nhận đúng nội dung biên bản.</label><label>Nếu có chỗ chưa đúng, ghi nội dung cần kiểm tra lại</label><textarea id="handoverMismatchNote" rows="2" placeholder="Ví dụ: thiếu 1 chìa khóa, chỉ số điện chưa đúng"></textarea><div class="modal-actions"><button type="button" class="save" id="confirmHandoverButton">Xác nhận nhận phòng</button><button type="button" id="reportHandoverMismatchButton">Báo cần kiểm tra lại</button><button type="button" onclick="this.closest('.modal-overlay').remove()">Để sau</button></div>`:`<div class="tenant-tabs-note">${record.status==='Đã được khách thuê xác nhận'?'Đã xác nhận bởi '+escapeHTML(record.confirmedBy||record.tenant)+' · '+escapeHTML(record.confirmedAt||''):'Trạng thái: '+escapeHTML(record.status||'Chờ khách thuê xác nhận')}</div><div class="modal-actions"><button type="button" onclick="this.closest('.modal-overlay').remove()">Đóng</button></div>`}</div>`;appendToPhone(pop);pop.querySelector('#confirmHandoverButton')?.addEventListener('click',()=>confirmRoomHandover(id));pop.querySelector('#reportHandoverMismatchButton')?.addEventListener('click',()=>reportHandoverMismatch(id))}
function setRoomCardStatus(room,status,tenantName=''){const card=cardForRoom(room);if(card){const badge=card.querySelector('.badge');if(badge){badge.innerText=status;badge.style.color=status==='Sửa chữa'?'#b83d39':status==='Trống'?'#bd6d23':'';badge.style.background=status==='Sửa chữa'?'#fae9e7':status==='Trống'?'#fbefe1':''}const sub=card.querySelector('.roomsub');if(sub&&tenantName)sub.innerText=tenantName}const statuses=JSON.parse(localStorage.getItem('homeRoomStatuses')||'{}');statuses[room]={status,tenantName,updatedAt:new Date().toISOString()};localStorage.setItem('homeRoomStatuses',JSON.stringify(statuses));const additions=readAllAdditionalRooms(),record=additions.find(item=>item.name===room);if(record){record.status=status;if(tenantName)record.tenantName=tenantName;localStorage.setItem('homeAdditionalRooms',JSON.stringify(additions))}updateRoomCounts()}
function reportHandoverMismatch(id){const account=document.getElementById('accountSelect').value.split('|'),record=readHandoverRecords().find(item=>String(item.id)===String(id));if(account[0]!=='tenant'||!record||record.room!==account[2]||record.status==='Đã được khách thuê xác nhận')return;const note=document.getElementById('handoverMismatchNote')?.value.trim();if(!note){alert('Anh ghi rõ tài sản hoặc chỉ số cần kiểm tra lại.');return}record.status='Khách báo sai lệch';record.tenantNote=note;record.reportedAt=new Date().toLocaleString('vi-VN');localStorage.setItem('homeInventoryRecords',JSON.stringify(readHandoverRecords().map(item=>String(item.id)===String(id)?record:item)));const all=JSON.parse(localStorage.getItem('homeTenantEvents')||'{}'),event=(all[record.room]||[]).find(item=>item.handoverId===record.id);if(event){event.status=record.status;event.detail+=' · Khách yêu cầu kiểm tra lại: '+note;event.tenantNote=note}localStorage.setItem('homeTenantEvents',JSON.stringify(all));document.querySelector('.modal-overlay')?.remove();setAccount(document.getElementById('accountSelect').value)}
