function renderManagerTenantQueue(){const box=document.getElementById('managerTenantRequests'),list=document.getElementById('managerRequestList');if(list&&!list.dataset.actionsBound){list.dataset.actionsBound='1';list.addEventListener('click',event=>{const button=event.target.closest('[data-request-action]');if(!button)return;if(button.dataset.requestAction==='payment'||button.dataset.requestAction==='accept')ackTenantRequest(button.dataset.room,button.dataset.id);else if(button.dataset.requestAction==='resolve')resolveTenantRepair(button.dataset.room,button.dataset.id);else if(button.dataset.requestAction==='review-handover')openHandoverReview(button.dataset.id);else if(button.dataset.requestAction==='open-room'){const card=cardForRoom(button.dataset.room);if(card)card.click()}})}const role=document.getElementById('accountSelect').value.split('|')[0];box.style.display='none';const all=JSON.parse(localStorage.getItem('homeTenantEvents')||'{}');const tenantNames={'P.302':'Minh Anh','P.203':'Quốc Bảo','P.101':'Thu Hà','P.205':'Gia Huy','P.401':'Mai Phương'};Object.entries(all).forEach(([room,events])=>events.forEach(event=>{if(!event.kind)event.kind=String(event.title||'').startsWith('Đã báo chuyển khoản:')?'payment':'repair';if(!event.id)event.id=String(Date.now())+Math.random().toString(16).slice(2);if(!event.tenantName)event.tenantName=tenantNames[room]||'Người thuê'}));localStorage.setItem('homeTenantEvents',JSON.stringify(all));const requests=Object.entries(all).flatMap(([room,events])=>events.filter(event=>event.kind==='repair'||event.kind==='payment'||event.kind==='handover').map(event=>({...event,room}))).filter(event=>propertyIdForRoom(event.room)===(readProperty().id||'HOME-001')&&(role!=='manager'||managerCanAccessRoom(document.getElementById('accountSelect').value.split('|')[1],event.room))).sort((a,b)=>{const rank=event=>event.status==='Khách báo sai lệch'?0:event.kind==='repair'?1:event.status==='Chờ khách thuê xác nhận'?2:3,priority=rank(a)-rank(b);if(priority)return priority;const da=a.date.split('/').reverse().join('-'),db=b.date.split('/').reverse().join('-');return new Date(db)-new Date(da)});const pending=requests.filter(event=>!['Đã xác nhận','Đã hoàn tất','Đã sửa','Từ chối'].includes(event.status));if(!pending.length){list.innerHTML='';return}box.style.display=['owner','manager'].includes(role)?'block':'none';document.getElementById('managerRequestCount').innerText=pending.length+' chờ xử lý / xác nhận';document.getElementById('managerRequestList').innerHTML=pending.map(event=>`<div class="manager-ticket">${event.photo?`<img src="${event.photo}" alt="Ảnh báo hư hỏng">`:''}<div class="ticket-meta">${escapeHTML(event.kind==='handover'?'Bàn giao phòng':event.kind==='repair'?'Báo hư hỏng':'Báo thanh toán')} · ${escapeHTML(event.date)} · ${escapeHTML(event.room)} · ${escapeHTML(propertyNameForRoom(event.room))}</div><h4>${escapeHTML(event.title.replace(/^Đã báo hư hỏng: |^Đã báo chuyển khoản: /,''))}</h4><p>${escapeHTML(event.detail)}</p><p>Người gửi: ${escapeHTML(event.tenantName||'Người thuê')} · <strong>${escapeHTML(event.status||'Chờ xử lý')}</strong></p>${event.status==='Chờ xử lý'?`<button data-request-action="${event.kind==='payment'?'payment':'accept'}" data-room="${escapeHTML(event.room)}" data-id="${escapeHTML(event.id)}">${event.kind==='payment'?'Xác nhận thanh toán':'Tiếp nhận yêu cầu'}</button>`:event.kind==='repair'&&event.status==='Đã tiếp nhận'?`<button data-request-action="resolve" data-room="${escapeHTML(event.room)}" data-id="${escapeHTML(event.id)}">Đánh dấu đã sửa</button>`:event.kind==='handover'?`<div class="ticket-meta">${event.confirmedBy?'Đã xác nhận bởi '+escapeHTML(event.confirmedBy):'Đang chờ khách thuê xác nhận từ tài khoản của mình'}</div><button data-request-action="review-handover" data-room="${escapeHTML(event.room)}" data-id="${escapeHTML(event.handoverId||'')}">Mở biên bản</button>${event.status==='Khách báo sai lệch'?`<button data-request-action="open-room" data-room="${escapeHTML(event.room)}">Mở phòng để lập lại biên bản</button>`:''}`:`<div class="ticket-meta">Đã tiếp nhận bởi ${escapeHTML(event.acceptedBy||'quản lý')}</div>`}</div>`).join('')}
function ackTenantRequest(room,id){const all=JSON.parse(localStorage.getItem('homeTenantEvents')||'{}');const event=(all[room]||[]).find(item=>item.id===id);if(!event)return;event.acceptedBy=document.getElementById('accountSelect').value.split('|')[1]||'Quản lý';if(event.kind==='payment'){event.status='Đã xác nhận';event.confirmedAt=new Date().toLocaleString('vi-VN');event.detail=String(event.detail||'').replace('Chờ quản lý xác nhận','Đã xác nhận bởi '+event.acceptedBy)}else{event.status='Đã tiếp nhận';event.detail=String(event.detail||'').replace('Chờ quản lý tiếp nhận','Đã tiếp nhận bởi '+event.acceptedBy)}localStorage.setItem('homeTenantEvents',JSON.stringify(all));renderManagerTenantQueue()}function resolveTenantRepair(room,id){const all=JSON.parse(localStorage.getItem('homeTenantEvents')||'{}');const event=(all[room]||[]).find(item=>item.id===id);if(!event)return;event.status='Đã hoàn tất';event.acceptedBy=document.getElementById('accountSelect').value.split('|')[1]||'Quản lý';event.resolvedAt=new Date().toLocaleString('vi-VN');event.detail=String(event.detail||'').replace(/ · (Chờ quản lý tiếp nhận|Đã tiếp nhận bởi [^·]*?)(?= · |$)/,'')+' · Đã xử lý xong bởi '+event.acceptedBy;localStorage.setItem('homeTenantEvents',JSON.stringify(all));renderManagerTenantQueue()}
