function readProperties(){if(window.HOME_REAL){try{const v=JSON.parse(localStorage.getItem('homeRealHouses')||'[]');if(Array.isArray(v)&&v.length)return v}catch{}}try{const saved=JSON.parse(localStorage.getItem('homeProperties')||'null'),legacy=JSON.parse(localStorage.getItem('homeProperty')||'null');let list=Array.isArray(saved)&&saved.length?saved:[legacy||{id:'HOME-001',name:'Nhà Phnom Penh',address:'Phnom Penh',currency:'USD',owner:'Anh Tuyên'}];const phnomPenh=list.find(item=>item.id==='HOME-001');if(phnomPenh&&/an\s*bình/i.test(phnomPenh.name||'')){phnomPenh.name='Nhà Phnom Penh';phnomPenh.address=phnomPenh.address||'Phnom Penh'}const daNang=list.find(item=>/đà\s*nẵng/i.test((item.name||'')+' '+(item.address||'')));if(daNang){daNang.currency='VND'}else{list.push({id:'HOME-DANANG',name:'Căn Đà Nẵng',address:'Đà Nẵng',currency:'VND',owner:'Anh Tuyên'})}const haNoi=list.find(item=>/hà\s*nội/i.test((item.name||'')+' '+(item.address||'')));if(haNoi){haNoi.name='Hà Nội';haNoi.address='Vĩnh Hưng';haNoi.currency='VND'}else{list.push({id:'HOME-HANOI',name:'Hà Nội',address:'Vĩnh Hưng',currency:'VND',owner:'Anh Tuyên'})}localStorage.setItem('homeProperties',JSON.stringify(list));return list}catch{return[{id:'HOME-001',name:'Nhà Phnom Penh',address:'Phnom Penh',currency:'USD',owner:'Anh Tuyên'},{id:'HOME-DANANG',name:'Căn Đà Nẵng',address:'Đà Nẵng',currency:'VND',owner:'Anh Tuyên'},{id:'HOME-HANOI',name:'Hà Nội',address:'Vĩnh Hưng',currency:'VND',owner:'Anh Tuyên'}]}}
function readProperty(){const list=readProperties(),active=localStorage.getItem('activeHomePropertyId'),property=list.find(item=>item.id===active)||list[0];localStorage.setItem('activeHomePropertyId',property.id);localStorage.setItem('homeProperties',JSON.stringify(list));localStorage.setItem('homeProperty',JSON.stringify(property));return property}
function propertyIdForRoom(room){try{const saved=JSON.parse(localStorage.getItem('homeAdditionalRooms')||'[]'),extra=Array.isArray(saved)&&saved.find(item=>item&&item.name===room&&item.propertyId);if(extra)return extra.propertyId}catch{}const homes=readProperties(),daNang=homes.find(item=>/đà\s*nẵng/i.test((item.name||'')+' '+(item.address||''))),haNoi=homes.find(item=>/hà\s*nội/i.test((item.name||'')+' '+(item.address||'')));if(['P.302','P.402','P.403','P.404','P.405','P.406','P.407'].includes(room))return daNang?.id||'HOME-DANANG';if(['P.501','P.502','P.503','P.504','P.505'].includes(room))return haNoi?.id||'HOME-HANOI';return homes.find(item=>/phnom\s*penh/i.test((item.name||'')+' '+(item.address||'')))?.id||homes[0]?.id||'HOME-001'}
