function readRoomManagerAssignments(){const seed=window.HOME_REAL?{}:{'P.302':'Tố Như','P.203':'Lộc','P.101':'A Thiện','P.205':'Nhi','P.401':'Nhi','P.403':'Hà','P.501':'Trang','P.503':'Trang'};let saved={};try{saved=JSON.parse(localStorage.getItem('homeRoomManagers')||'{}')||{}}catch{}const migrated=localStorage.getItem('homeRoomManagersVersion')!=='3',assignments={...seed,...saved};if(migrated)Object.keys(assignments).forEach(room=>{if(assignments[room]==='Như')assignments[room]='Tố Như'});Object.entries(assignments).forEach(([room,manager])=>{if(manager&&!managerCanAccessProperty(manager,propertyIdForRoom(room)))delete assignments[room]});if(migrated)Object.entries(seed).forEach(([room,manager])=>{if(!assignments[room]&&managerCanAccessProperty(manager,propertyIdForRoom(room)))assignments[room]=manager});['P.402','P.502'].forEach(room=>{if(!getHomeContract(room))delete assignments[room]});localStorage.setItem('homeRoomManagers',JSON.stringify(assignments));localStorage.setItem('homeRoomManagersVersion','3');return Object.fromEntries(Object.entries(assignments).filter(([,manager])=>manager))}
