function openPropertyForm(startCreating=true){const role=document.getElementById('accountSelect').value.split('|')[0];if(!['owner','manager'].includes(role))return;let properties=readProperties(),selected=readProperty(),editable=role==='owner',creating=!!startCreating,managerAssignments=readPropertyManagerAssignments();const overlay=document.createElement('div');overlay.className='modal-overlay';function draw(){overlay.innerHTML=`<form class="modal-sheet"><div class="modal-head">${creating?'Thêm căn nhà mới':editable?'Quản lý căn nhà':'Thông tin căn nhà'}</div>${creating?'':`<label>Chọn căn nhà</label><select name="propertyChoice" ${editable?'':'disabled'}>${properties.map(item=>`<option value="${escapeHTML(item.id)}" ${item.id===selected.id?'selected':''}>${escapeHTML(item.name)} · ${item.currency==='VND'?'VND':'USD'}</option>`).join('')}</select>`}<label>Tên căn nhà</label><input name="name" required maxlength=160 value="${creating?'':escapeHTML(selected.name)}" placeholder="Ví dụ: Nhà Phnom Penh" ${editable?'':'readonly'}><label>Địa chỉ</label><input name="address" required maxlength=500 value="${creating?'':escapeHTML(selected.address||'')}" placeholder="Số nhà, đường, phường/xã, tỉnh/thành phố" ${editable?'':'readonly'}><label>Tiền tệ của căn nhà</label><select name="currency" ${editable?'':'disabled'}><option value="USD" ${(creating||selected.currency!=='VND')?'selected':''}>USD · Đô la Mỹ</option><option value="VND" ${selected.currency==='VND'&&!creating?'selected':''}>VND · Việt Nam đồng</option></select><p class="note">Tất cả tiền thuê, tiền cọc, thanh toán và chi phí dùng cùng đơn vị. Chọn đúng tiền tệ trước khi nhập dữ liệu; đổi lựa chọn không tự quy đổi số tiền đã có.</p><label>Quản lý được chủ nhà giao cho căn này</label><div class="manager-checks">${readUsers().filter(user=>user.role==='manager'&&(user.status!=='Tạm khóa'||(!creating&&(managerAssignments[selected.id]||[]).includes(user.name)))).map(user=>user.name).map(manager=>`<label class="user-check"><input type="checkbox" name="assignedManagers" value="${escapeHTML(manager)}" ${!creating&&(managerAssignments[selected.id]||[]).includes(manager)?'checked':''} ${editable?'':'disabled'}><span>${escapeHTML(manager)}</span></label>`).join('')}</div><p class="note">Có thể giao nhiều quản lý cho căn nhà. Mỗi phòng đang thuê chỉ được phân công một quản lý.</p><div class="modal-actions">${editable?`${creating?(startCreating?'<button type="button" data-close>Huỷ</button>':'<button type="button" data-cancel-create>Huỷ</button>'):'<button type="button" data-add-property>＋ Thêm căn nhà</button><button type="button" data-close>Đóng</button>'}<button class="save" type="submit">${creating?'Tạo căn nhà':'Lưu thông tin'}</button>`:'<button type="button" data-close>Đóng</button>'}</div></form>`;overlay.querySelector('[data-close]')?.addEventListener('click',()=>overlay.remove());overlay.querySelector('[data-add-property]')?.addEventListener('click',()=>{creating=true;draw()});overlay.querySelector('[data-cancel-create]')?.addEventListener('click',()=>{creating=false;draw()});overlay.querySelector('[name="propertyChoice"]')?.addEventListener('change',event=>{selected=properties.find(item=>item.id===event.target.value)||selected;creating=false;localStorage.setItem('activeHomePropertyId',selected.id);localStorage.setItem('homeProperty',JSON.stringify(selected));location.reload()});overlay.querySelector('form').addEventListener('submit',event=>{event.preventDefault();if(!editable)return;const data=new FormData(event.currentTarget),name=String(data.get('name')||'').trim(),address=String(data.get('address')||'').trim(),error=message=>{let item=overlay.querySelector('.form-error');if(!item){item=document.createElement('p');item.className='form-error';item.style='color:#b83d39;font-size:12px;margin:12px 0 0';overlay.querySelector('.modal-actions').before(item)}item.textContent=message};if(name.length<2){error('Tên căn nhà cần có ít nhất 2 ký tự.');return}if(!address){error('Nhập địa chỉ để phân biệt căn nhà và dùng trên hồ sơ thuê.');return}if(creating){selected={id:'HOME-'+Date.now(),name,address,currency:String(data.get('currency')||'USD'),owner:'Anh Tuyên',createdAt:new Date().toISOString()};properties.push(selected)}else{selected={...selected,name,address,currency:String(data.get('currency')||'USD'),owner:'Anh Tuyên',updatedAt:new Date().toLocaleString('vi-VN')};properties=properties.map(item=>item.id===selected.id?selected:item)}managerAssignments[selected.id]=data.getAll('assignedManagers').map(String);localStorage.setItem('homePropertyManagers',JSON.stringify(managerAssignments));localStorage.setItem('homeProperties',JSON.stringify(properties));localStorage.setItem('activeHomePropertyId',selected.id);localStorage.setItem('homeProperty',JSON.stringify(selected));location.reload()})};appendToPhone(overlay);draw()}
function openPropertyPicker(anchor){const [role,managerName]=document.getElementById('accountSelect').value.split('|');if(!['owner','manager'].includes(role)||(role==='manager'&&readProperties().filter(item=>managerCanAccessProperty(managerName,item.id)).length<=1))return;const existing=document.getElementById('propertyDropdown');if(existing){existing.remove();return}const active=readProperty(),visibleProperties=role==='manager'?readProperties().filter(item=>managerCanAccessProperty(managerName,item.id)):readProperties(),list=visibleProperties,context=(anchor&&anchor.closest&&anchor.closest('.subpage .head'))||document.querySelector('.management-overview-head'),panel=document.createElement('div');panel.id='propertyDropdown';panel.className='property-dropdown';panel.innerHTML=`<div class="property-dropdown-title">Chọn căn nhà</div>${role==='manager'&&!list.length?'<p class="note">Chủ nhà chưa giao căn nhà nào cho tài khoản này.</p>':''}${list.map(item=>`<button type="button" class="property-picker-item" data-property-id="${escapeHTML(item.id)}"><span><strong>${escapeHTML(item.name)}</strong><small>${escapeHTML(item.address||'Chưa có địa chỉ')}</small></span><span>${item.currency==='VND'?'VND':'USD'}${item.id===active.id?'　✓':''}</span></button>`).join('')}${role==='owner'?'<button type="button" class="property-add-inline" data-add>＋ Thêm căn nhà</button>':''}`;context.append(panel);panel.addEventListener('click',event=>{const item=event.target.closest('[data-property-id]');if(item){const selected=list.find(property=>property.id===item.dataset.propertyId);localStorage.setItem('activeHomePropertyId',selected.id);localStorage.setItem('homeProperty',JSON.stringify(selected));try{sessionStorage.setItem('homeReturnTab',document.querySelector('.subpage.active')?.id||'home')}catch{}location.reload();return}if(event.target.closest('[data-add]')){panel.remove();openPropertyForm(true)}});setTimeout(()=>{const close=e=>{if(!context.contains(e.target)){panel.remove();document.removeEventListener('click',close)}};document.addEventListener('click',close)},0)}document.getElementById('propertyButton')?.addEventListener('click',openPropertyPicker);refreshPropertyName();
function readRoomApprovalRequests(){try{return JSON.parse(localStorage.getItem('homeRoomApprovalRequests')||'[]')}catch{return[]}}
function renderRoomApprovalRequests(){const role=document.getElementById('accountSelect').value.split('|')[0];let box=document.getElementById('roomApprovalRequests');if(!box){box=document.createElement('div');box.id='roomApprovalRequests';box.className='tenant-card';document.getElementById('managerTenantRequests').before(box);box.addEventListener('click',event=>{const button=event.target.closest('[data-room-review]');if(!button)return;const id=button.dataset.id,requests=readRoomApprovalRequests(),request=requests.find(item=>item.id===id);const currentRole=document.getElementById('accountSelect').value.split('|')[0];if(!request||currentRole!=='owner')return;if(button.dataset.roomReview==='reject-open'){const form=box.querySelector('[data-reject-form="'+CSS.escape(id)+'"]');if(form)form.hidden=false;return}if(button.dataset.roomReview==='approve'){request.status='Đã duyệt';request.reviewedBy=document.getElementById('accountSelect').value.split('|')[1];request.reviewedAt=new Date().toLocaleString('vi-VN');localStorage.setItem('homeRoomApprovalRequests',JSON.stringify(requests));localStorage.setItem('homeAdditionalRooms',JSON.stringify([...readAllAdditionalRooms(),{...request.room,propertyId:request.propertyId,approved:true}]));restoreAdditionalRooms();restoreDeletedRooms();wireRoomCards();updateRoomCounts();renderHouseInventorySummary();renderRoomApprovalRequests();renderDbTable();return}if(button.dataset.roomReview==='reject'){const form=button.closest('[data-reject-form]'),reason=form.querySelector('textarea').value.trim();if(!reason){form.querySelector('.form-error').textContent='Nhập lý do từ chối để quản lý biết cần sửa gì.';return}request.status='Từ chối';request.reviewedBy=document.getElementById('accountSelect').value.split('|')[1];request.reviewedAt=new Date().toLocaleString('vi-VN');request.reviewNote=reason;localStorage.setItem('homeRoomApprovalRequests',JSON.stringify(requests));renderRoomApprovalRequests();renderDbTable()}})}const propertyId=readProperty().id||'HOME-001',all=readRoomApprovalRequests(),visible=role==='owner'?all.filter(item=>item.status==='Chờ duyệt'&&item.propertyId===propertyId):role==='manager'?all.filter(item=>item.requestedBy===document.getElementById('accountSelect').value.split('|')[1]&&item.propertyId===propertyId):[];box.style.display=visible.length?'block':'none';if(!visible.length)return;box.innerHTML=`<div class=\"tenant-title\">${role==='owner'?'Phòng chờ chủ nhà duyệt':'Đề xuất phòng của anh'} · ${escapeHTML(readProperty().name||'Căn nhà')} <span class=\"tenant-asset-count\">${visible.filter(item=>item.status==='Chờ duyệt').length} chờ duyệt</span></div>`+visible.map(item=>`<div class=\"report\"><h3>${escapeHTML(item.room.name)} · ${escapeHTML(readProperty().name||'Căn nhà')} · ${escapeHTML(item.room.type)} · ${Number(item.room.area)} m²</h3><div class=\"entry\"><span>Giá thuê</span><span>${money(item.room.rent)}/tháng</span></div><div class=\"entry\"><span>Đề xuất bởi</span><span>${escapeHTML(item.requestedBy)}</span></div><div class=\"tenant-tabs-note\">${escapeHTML(item.status)}${item.reviewNote?' · Lý do: '+escapeHTML(item.reviewNote):''}</div>${role==='owner'&&item.status==='Chờ duyệt'?`<div class=\"modal-actions\"><button data-room-review=\"approve\" data-id=\"${escapeHTML(item.id)}\">Duyệt tạo phòng</button><button data-room-review=\"reject-open\" data-id=\"${escapeHTML(item.id)}\">Từ chối</button></div><div data-reject-form=\"${escapeHTML(item.id)}\" hidden><textarea placeholder=\"Lý do từ chối\" style=\"width:100%;min-height:60px;border:1px solid #e6dccd;border-radius:10px;padding:9px\"></textarea><p class=\"form-error\" style=\"color:#b83d39;font-size:11px\"></p><button data-room-review=\"reject\" data-id=\"${escapeHTML(item.id)}\">Gửi từ chối</button></div>`:''}</div>`).join('')}
