function expenseLimit(propertyId){const home=readProperties().find(item=>item.id===propertyId);if(home&&home.smallExpenseLimit!=null&&home.smallExpenseLimit!=='')return Number(home.smallExpenseLimit);return home?.currency==='VND'?500000:20}
function expensePeers(record){const house=record.propertyId||'HOME-001';return (readPropertyManagerAssignments()[house]||[]).filter(manager=>manager!==record.createdBy&&!isUserLocked('manager|'+manager+'|'))}
function expenseIsCommon(record){return !(record.room||(String(record.scope||'').match(/P\.\d+/)||[])[0])}
