function peersLeft(record){return (expenseIsCommon(record)?commonCostPeers(record):expensePeers(record)).filter(name=>!peerApproved(record,name))}
function peerStageDone(record){const peers=expenseIsCommon(record)?commonCostPeers(record):expensePeers(record);if(!peers.length)return true;return expenseIsCommon(record)?peers.every(name=>peerApproved(record,name)):peers.some(name=>peerApproved(record,name))}
