function receiveRemit(houseId,month,name){saveSettlement(houseId,month,record=>{const remit=record.remits[name];if(!remit?.pending)return;const pending=remit.pending,due=Math.abs(record.snapshot?.managers?.[name]?.mustRemit||0);remit.received=roundForHouse((Number(remit.received)||0)+Number(pending.amount),houseId);remit.history=[...(remit.history||[]),{...pending,receivedAt:new Date().toLocaleString('vi-VN'),receivedBy:currentActorName()}];remit.pending=null;const gap=roundForHouse(due-remit.received,houseId);settlementLog(record,(remit.direction==='toOwner'?'Chủ nhà xác nhận đã nhận từ '+name+' ':name+' xác nhận đã nhận ')+amountForHouse(pending.amount,houseId)+(gap>0.005?' · còn thiếu '+amountForHouse(gap,houseId):gap<-0.005?' · dư '+amountForHouse(-gap,houseId):''));const data=record.snapshot;if(data&&Object.keys(data.managers).every(person=>{const owed=Math.abs(data.managers[person].mustRemit);return !owed||(Number(record.remits?.[person]?.received)||0)>=owed-0.005})){record.lockedAt=new Date().toLocaleString('vi-VN');settlementLog(record,'Khóa sổ '+monthLabel(month))}});renderManagementOverview()}
function custodySummary(houseId){const owner=ownerName(),settlements=Object.values(readSettlements()).filter(item=>item.houseId===houseId),people={},person=name=>people[name]=people[name]||{name,collected:0,paid:0,remitted:0,received:0,shares:0,deposits:0,depositRooms:[]};incomeEntries(houseId).forEach(item=>{if(item.holder!==owner)person(item.holder).collected+=item.amount});expenseEntries(houseId).forEach(item=>{if(item.payer!==owner)person(item.payer).paid+=item.amount});settlements.forEach(record=>{Object.entries(record.remits||{}).forEach(([name,remit])=>{const value=Number(remit.received)||0;if(!value)return;if(remit.direction==='toOwner')person(name).remitted+=value;else person(name).received+=value});if(record.approvedAt&&record.snapshot)Object.entries(record.snapshot.managers||{}).forEach(([name,item])=>{person(name).shares+=Number(item.share)||0})});const managers=readRoomManagerAssignments();collectRoomRecords(true).records.filter(room=>room.house===houseId&&room.status==='Đang thuê').forEach(room=>{const contract=getHomeContract(room.code),holder=managers[room.code]||owner;if(holder===owner||!contract||depositUnpaid(room.code))return;const entry=person(holder);entry.deposits+=Number(contract.deposit)||0;entry.depositRooms.push(room.code)});return Object.values(people).map(entry=>({...entry,ownerMoney:roundForHouse(entry.collected-entry.paid-entry.remitted+entry.received-entry.shares,houseId)}))}
