document.getElementById('finance')?.addEventListener('click',event=>{const view=event.target.closest('[data-fin-view]');if(view){financeView=view.dataset.finView;renderFinancePage();return}const houseId=readProperty().id||'HOME-001',month=event.target.closest('[data-settle-month]');if(month){settleMonth=shiftMonth(settleMonth||monthKeyOf(Date.now()),Number(month.dataset.settleMonth));renderFinancePage();return}if(event.target.closest('[data-settle-confirm]')){confirmSettlement(houseId,settleMonth);return}if(event.target.closest('[data-settle-approve]')){appConfirm('Xác nhận chốt '+monthLabel(settleMonth)+'?','Số liệu quản lý gửi sẽ được cố định. Sau đó quản lý nộp tiền và anh xác nhận đã nhận để khóa sổ.','Xác nhận chốt',()=>approveSettlement(houseId,settleMonth));return}const remit=event.target.closest('[data-settle-remit]');if(remit){openRemitForm(houseId,settleMonth,remit.dataset.settleRemit);return}const receive=event.target.closest('[data-settle-receive]');if(receive)receiveRemit(houseId,settleMonth,receive.dataset.settleReceive)},true);
function readCheckouts(){try{const value=JSON.parse(localStorage.getItem('homeCheckouts')||'{}');return value&&typeof value==='object'?value:{}}catch{return{}}}
