function roomTenantUser(room){const list=readUsers().filter(user=>user.role==='tenant'&&user.room===room&&user.status!=='Đã xoá');if(list.length<2)return list[0];const name=String(getHomeContract(room)?.tenantName||'').trim();return (name&&list.find(user=>user.name===name))||list[0]}
function roomDepositAmount(room){const contract=getHomeContract(room);return Number(contract?.deposit??tenantProfiles[room]?.deposit)||0}
