function checkoutDeductionText(record){return (record.deductions||[]).map(item=>item.reason+' '+amountForHouse(item.amount,record.house)).join(', ')}
function clearRoomTenantCard(room){const card=cardForRoom(room);if(!card)return;card.querySelector('[title="Khách thuê"]')?.remove();const sub=card.querySelector('.roomsub');if(sub&&!sub.textContent.trim())sub.textContent='Chưa có khách'}
