function markRenewedProfiles(){Object.entries(readHomeContracts()).forEach(([room,contract])=>{if(!contract?.renewedAt||!tenantProfiles[room])return;tenantProfiles[room]={...tenantProfiles[room],term:contract.term,rent:contract.rent,contractStatus:'Còn hiệu lực',dueNote:tenantProfiles[room].dueNote&&/kết thúc|gia hạn/i.test(tenantProfiles[room].dueNote)?'Đã gia hạn đến '+(contract.term.match(/\d{1,2}\/\d{1,2}\/\d{4}/g)||[]).pop():tenantProfiles[room].dueNote}})}
const collectWorkItemsChargeBase=collectWorkItems;collectWorkItems=function(){const items=collectWorkItemsChargeBase(),scope=workScope();if(!['owner','manager'].includes(scope.role))return items;const today=dayStart(),charges=ensureRentCharges(),pendingReport=room=>(readTenantEventsSafe()[room]||[]).some(event=>event.kind==='payment'&&(event.status==='Chờ xử lý'||!event.status));charges.forEach(item=>{if(item.status!=='Chưa thu'||!scope.houseOk(item.house)||!(scope.roomOk(item.room)||(scope.role==='manager'&&item.collector===scope.name))||pendingReport(item.room)||(vacatedRoom(item.room)&&!item.collector&&!item.extra))return;if(item.due-today>RENT_REMIND_DAYS*DAY_MS)return;const late=Math.round((today-item.due)/DAY_MS);items.push({type:'payment',house:item.house,room:item.room,title:item.room+': thu '+item.title.toLocaleLowerCase()+' · '+item.tenantName,sub:(late>0?'Quá hạn '+late+' ngày':late===0?'Hạn hôm nay':'Hạn '+viDate(item.due))+' · '+amountForHouse(item.amount,item.house),time:item.due,actions:[{label:'Đã thu',run:()=>askChargePaid(item.id)}],target:{type:'room',room:item.room}})});collectRoomRecords(true).records.filter(record=>record.status==='Đang thuê'&&scope.houseOk(record.house)&&scope.roomOk(record.code)).forEach(record=>{const room=record.code,lease=roomLease(room),user=roomTenantUser(room);if(!lease.end||!user||moveOutRequest(room)||(readCheckouts()[room]&&readCheckouts()[room].status!=='Đã hoàn cọc'))return;const left=Math.round((dayStart(lease.end)-today)/DAY_MS);if(left>LEASE_REMIND_DAYS)return;const pending=lease.raw?.renewal?.status==='Chờ chủ nhà duyệt',renewal=lease.raw?.renewal;if(pending){items.push({type:'contract',house:record.house,room,title:room+': '+(scope.role==='owner'?'duyệt gia hạn hợp đồng ':'chờ chủ nhà duyệt gia hạn · ')+user.name,sub:'Đến '+renewal.end+' · '+amountForHouse(renewal.rent,record.house)+'/tháng · đề xuất bởi '+renewal.by,time:parseViTime(renewal.at),actions:scope.role==='owner'?[{label:'Duyệt',run:()=>applyRenewal(room,renewal)}]:[],target:{type:'room',room}});return}const can=canManageCheckout(room,scope);items.push({type:'contract',house:record.house,room,title:room+': hợp đồng '+user.name+' hết hạn '+viDate(lease.end),sub:(left<0?'Đã quá hạn '+(-left)+' ngày':left===0?'Hết hạn hôm nay':'Còn '+left+' ngày')+' · gia hạn hoặc trả phòng',time:lease.end,actions:can?[{label:'Gia hạn',run:()=>openRenewForm(room)},{label:'Trả phòng',run:()=>openCheckoutForm(room)}]:[],target:{type:'room',room}})});return items};
const renderTenantConfirmationsChargeBase=renderTenantConfirmations;renderTenantConfirmations=function(){renderTenantConfirmationsChargeBase();const account=document.getElementById('accountSelect').value,[role,,room]=account.split('|');if(role!=='tenant')return;ensureRentCharges();const record=readCheckouts()[room],legacy=tenantProfiles[room]?.seedConfirmed?[]:roomOutstandingDebts(room).map(d=>({title:d.title,amount:d.amount,due:parseViTime(tenantProfiles[room]?.dueDate)||dayStart()-DAY_MS,legacy:true})),open=[...legacy,...openRentCharges(room,account)].sort((a,b)=>a.due-b.due);if(!open.length)return;const house=propertyIdForRoom(room),today=dayStart(),first=open[0],late=first.due<today,setText=(id,text)=>{const el=document.getElementById(id);if(el)el.textContent=text};setText('tenantDueDate',viDate(first.due));setText('tenantDueStatus',late?'Quá hạn':first.due===today?'Hạn hôm nay':'Sắp đến hạn');const cutoff=Math.max(dayStart(first.due),today),now=open.filter(item=>dayStart(item.due)<=cutoff),later=open.filter(item=>dayStart(item.due)>cutoff);setText('tenantDueAmount',amountForHouse(now.reduce((sum,item)=>sum+item.amount,0),house));setText('tenantDueCopy',now.map(item=>item.title+' '+amountForHouse(item.amount,house)).join(' · ')+(later.length?' · Sắp tới: '+later.map(item=>item.title+' '+amountForHouse(item.amount,house)+' (hạn '+viDate(item.due)+')').join(' · '):''));document.getElementById('tenantDueCard')?.classList.toggle('late',late);const payButton=document.querySelector('#tenantPortal .tenant-actions button.primary');if(payButton&&!payButton.hidden)payButton.style.display='inline-flex';if(late){const days=Math.round((today-first.due)/DAY_MS);setText('tenantDueStatus','Quá hạn '+days+' ngày')}};
