const LOGIN_COUNTRIES={'84':{flag:'🇻🇳',hint:'0901 234 567'},'855':{flag:'🇰🇭',hint:'012 345 678'}};
const LOGIN_MAX_FAILS=5,LOGIN_LOCK_MINUTES=5;
function loginLang(){const saved=localStorage.getItem('homeLang');if(LOGIN_TEXT[saved])return saved;const device=(navigator.languages||[navigator.language||'']).map(item=>String(item).slice(0,2).toLowerCase());return device.find(code=>LOGIN_TEXT[code])||'vi'}
function loginCountry(){const saved=localStorage.getItem('homeLoginCC');return LOGIN_COUNTRIES[saved]?saved:loginLang()==='km'?'855':'84'}
// Số điện thoại dạng quốc tế (chỉ chữ số). Số lưu không có dấu + được coi là số Việt Nam.
function phoneKey(value,country){const raw=String(value||'').trim();let digits=raw.replace(/\D/g,'');if(!digits)return'';if(raw.startsWith('+'))return digits;if(digits.startsWith('00'))return digits.slice(2);if(digits.startsWith('0'))return country+digits.slice(1);return country+digits}
function isCambodiaHouse(houseId){const house=readProperties().find(item=>item.id===houseId);return /phnom penh|campuchia|cambodia|kampuchea/i.test(String(house?.name||'')+' '+String(house?.address||''))}
function phoneWithCountry(phone,room){const value=String(phone||'').trim();if(!value||value.startsWith('+'))return value;return isCambodiaHouse(propertyIdForRoom(room))?'+855 '+value.replace(/^0/,''):value}
function readLoginFails(){try{const data=JSON.parse(localStorage.getItem('homeLoginFails')||'{}');return data&&typeof data==='object'?data:{}}catch{return{}}}
function loginLockMinutes(key){const until=readLoginFails()[key]?.until||0;return until>Date.now()?Math.ceil((until-Date.now())/60000):0}
function noteLoginFail(key){const all=readLoginFails(),entry=all[key]||{count:0};entry.count=(entry.until&&entry.until<=Date.now()?0:entry.count||0)+1;entry.until=0;if(entry.count>=LOGIN_MAX_FAILS){entry.count=0;entry.until=Date.now()+LOGIN_LOCK_MINUTES*60000}all[key]=entry;localStorage.setItem('homeLoginFails',JSON.stringify(all));return entry.until?LOGIN_LOCK_MINUTES:0}
function clearLoginFails(key){const all=readLoginFails();if(all[key]){delete all[key];localStorage.setItem('homeLoginFails',JSON.stringify(all))}}
function readPasswords(){try{const data=JSON.parse(localStorage.getItem('homePasswords')||'{}');return data&&typeof data==='object'&&!Array.isArray(data)?data:{}}catch{return{}}}
function passwordRecord(key){return readPasswords()[key]||null}
function userPassword(key){return passwordRecord(key)?.pw||DEMO_PASSWORD}
function setUserPassword(key,pw,by,selfChanged){if(!key||!pw)return;const all=readPasswords();all[key]={pw,by:by||'',at:new Date().toLocaleString('vi-VN'),self:!!selfChanged};localStorage.setItem('homePasswords',JSON.stringify(all))}
function randomPassword(){return String(Math.floor(100000+Math.random()*900000))}
function loginAccounts(){return [OWNER_ACCOUNT,...readUsers()]}
function accountByKey(key){return loginAccounts().find(user=>user.key===key)||null}
function canResetPassword(user){const [role,name]=document.getElementById('accountSelect').value.split('|');if(!user||user.key===document.getElementById('accountSelect').value)return false;if(role==='owner')return true;return role==='manager'&&user.role==='tenant'&&readRoomManagerAssignments()[user.room]===name}
function signInAs(key){localStorage.removeItem('homeSignedOut');document.getElementById('loginScreen')?.remove();const record=passwordRecord(key);if(!record||!record.self)sessionStorage.setItem('homePwNudge',key);const select=document.getElementById('accountSelect');select.value=key;setAccount(key);const homeTab=document.querySelector('.tab[data-id="home"]');if(homeTab)go('home',homeTab);setTimeout(maybeNudgePassword,300)}
const LOGIN_ICONS={globe:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.3"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.6 2.6 2.6 15.4 0 18M12 3c-2.6 2.6-2.6 15.4 0 18"/></svg>',phone:'<svg viewBox="0 0 24 24" fill="none" stroke="#173f2f" stroke-width="2" stroke-linecap="round"><rect x="6" y="2.5" width="12" height="19" rx="3"/><path d="M10.5 18.5h3"/></svg>',lock:'<svg viewBox="0 0 24 24" fill="none" stroke="#173f2f" stroke-width="2" stroke-linecap="round"><rect x="4.5" y="10" width="15" height="11" rx="2.5"/><path d="M8 10V7.5a4 4 0 0 1 8 0V10"/><circle cx="12" cy="15.5" r="1.3" fill="#173f2f" stroke="none"/></svg>',eye:'<svg viewBox="0 0 24 24" fill="none" stroke="#173f2f" stroke-width="1.8" stroke-linecap="round"><path d="M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12Z"/><circle cx="12" cy="12" r="3"/></svg>',eyeOff:'<svg viewBox="0 0 24 24" fill="none" stroke="#173f2f" stroke-width="1.8" stroke-linecap="round"><path d="M2.5 12S6 5.5 12 5.5c2 0 3.7.7 5.1 1.7M21.5 12s-3.5 6.5-9.5 6.5c-2 0-3.7-.7-5.1-1.7"/><path d="M9.9 14.1a3 3 0 0 0 4.2-4.2M3.5 3.5l17 17"/></svg>',arrow:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12h16M14 6l6 6-6 6"/></svg>',chevron:'<svg viewBox="0 0 24 24" fill="none" stroke="#123a2b" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>',house:'<svg viewBox="0 0 24 24" fill="none" stroke="#173f2f" stroke-width="1.8" stroke-linejoin="round"><path d="M3.5 11 12 4l8.5 7"/><path d="M5.5 9.5V20h13V9.5"/><path d="M10 20v-5h4v5"/></svg>'};
function renderLoginScreen(state={}){const phone=document.querySelector('.phone');if(!phone)return;document.getElementById('loginScreen')?.remove();const lang=loginLang(),t=LOGIN_TEXT[lang],cc=state.cc||loginCountry(),country=LOGIN_COUNTRIES[cc],box=document.createElement('div');box.id='loginScreen';box.className='login-screen lang-'+lang+(phone.clientHeight<760?' compact':'');box.lang=lang;const langNames={vi:['Vi','Tiếng Việt'],km:['ខ្មែរ','ភាសាខ្មែរ'],en:['EN','English']};box.innerHTML=`<div class="login-lang" role="group"><span class="globe">${LOGIN_ICONS.globe}</span>${Object.entries(langNames).map(([code,[short,name]],index)=>`${index?'<i></i>':''}<button type="button" data-lang="${code}" class="${code===lang?'on':''}" aria-label="${name}" aria-pressed="${code===lang}">${short}</button>`).join('')}</div><div class="login-top"></div><div class="login-brand"><span class="app-logo" aria-hidden="true"></span><h1>Home</h1><p>${t.sub}</p><hr></div><form class="login-card" novalidate>${state.matches?`<p class="login-pick-title">${t.pick}</p><div class="login-pick">${state.matches.map(user=>`<button type="button" data-pick="${escapeHTML(user.key)}">${escapeHTML(user.fullName||user.name)}<small>${t[user.role]}${user.room?' · '+escapeHTML(user.room):''}</small></button>`).join('')}</div><button type="button" class="login-back" data-back>${t.back}</button>`:`<div class="login-field">${LOGIN_ICONS.phone}<div><label for="loginPhone">${t.phone}</label><div class="login-row"><button type="button" class="login-cc" data-cc aria-label="${t.cc}">${country.flag} +${cc}${LOGIN_ICONS.chevron}</button><input id="loginPhone" name="phone" type="tel" inputmode="tel" autocomplete="username" placeholder="${t.example}${country.hint}" value="${escapeHTML(state.phone||'')}"></div></div></div><div class="login-field">${LOGIN_ICONS.lock}<div><label for="loginPassword">${t.pw}</label><input id="loginPassword" name="password" type="password" autocomplete="current-password" placeholder="${t.pwHint}"></div><button type="button" data-toggle-pw aria-label="${t.show}">${LOGIN_ICONS.eyeOff}</button></div>${state.error?`<div class="login-error" role="alert">${t[state.error].replace('{m}',state.minutes||LOGIN_LOCK_MINUTES)}</div>`:''}<button type="submit" class="login-submit">${t.go}${LOGIN_ICONS.arrow}</button><button type="button" class="login-forgot" data-forgot>${t.forgot}</button><div class="login-help" hidden>${t.forgotHelp}</div>`}</form><div class="login-foot">${LOGIN_ICONS.house}<strong>${t.footTitle}</strong>${t.footText}</div><div class="login-legal"><button type="button" data-legal="privacy">${t.privacy}</button><span>·</span><button type="button" data-legal="terms">${t.terms}</button></div>`;phone.append(box);const passwordInput=box.querySelector('#loginPassword');if(passwordInput&&state.password)passwordInput.value=state.password;const keep=()=>({phone:box.querySelector('#loginPhone')?.value??state.phone,password:box.querySelector('#loginPassword')?.value??state.password,error:state.error,minutes:state.minutes,matches:state.matches});
box.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.lang===lang)return;localStorage.setItem('homeLang',button.dataset.lang);renderLoginScreen({...keep(),cc})}));box.querySelector('[data-cc]')?.addEventListener('click',()=>{const next=cc==='84'?'855':'84';localStorage.setItem('homeLoginCC',next);renderLoginScreen({...keep(),cc:next,error:null});document.getElementById('loginPhone')?.focus()});box.querySelectorAll('[data-pick]').forEach(button=>button.addEventListener('click',()=>signInAs(button.dataset.pick)));box.querySelector('[data-back]')?.addEventListener('click',()=>renderLoginScreen({phone:state.phone,cc}));box.querySelectorAll('[data-legal]').forEach(button=>button.addEventListener('click',()=>openLegal(button.dataset.legal)));const toggle=box.querySelector('[data-toggle-pw]');if(toggle)toggle.addEventListener('click',()=>{const input=box.querySelector('#loginPassword'),showing=input.type==='text';input.type=showing?'password':'text';toggle.innerHTML=showing?LOGIN_ICONS.eyeOff:LOGIN_ICONS.eye;toggle.setAttribute('aria-label',showing?t.show:t.hide)});box.querySelector('[data-forgot]')?.addEventListener('click',()=>{const help=box.querySelector('.login-help');help.hidden=!help.hidden});box.querySelectorAll('.login-field input').forEach(input=>input.addEventListener('focus',()=>setTimeout(()=>input.closest('.login-field').scrollIntoView({block:'center',behavior:'smooth'}),250)));
if(state.error){const target=state.error==='empty'&&!state.phone?box.querySelector('#loginPhone'):box.querySelector('#loginPassword');if(target){target.focus({preventScroll:true});if(state.error!=='empty')target.select?.()}}
box.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const submit=box.querySelector('.login-submit');if(!submit||submit.disabled)return;const phoneValue=box.querySelector('#loginPhone').value,password=box.querySelector('#loginPassword').value,key=phoneKey(phoneValue,cc);if(!key||!password)return renderLoginScreen({phone:phoneValue,password,cc,error:'empty'});const wait=loginLockMinutes(key);if(wait)return renderLoginScreen({phone:phoneValue,cc,error:'tooMany',minutes:wait});submit.disabled=true;submit.innerHTML='<span class="login-spin" aria-label="…"></span>';setTimeout(()=>{const found=loginAccounts().filter(user=>user.phone&&phoneKey(user.phone,'84')===key&&userPassword(user.key)===password);if(!found.length){const locked=noteLoginFail(key);return renderLoginScreen({phone:phoneValue,cc,error:locked?'tooMany':otherCountryMatch(phoneValue,cc,password)?'otherCc':'wrong',minutes:locked||(otherCountryMatch(phoneValue,cc,password)||'')})}const usable=found.filter(user=>!['Tạm khóa','Đã xoá'].includes(user.status));if(!usable.length)return renderLoginScreen({phone:phoneValue,cc,error:found.some(user=>user.status==='Tạm khóa')?'locked':'deleted'});clearLoginFails(key);if(usable.length>1&&!usable.every(user=>user.role==='tenant'))return renderLoginScreen({phone:phoneValue,cc,matches:usable});signInAs(usable[0].key)},450)})}
const LEGAL_TEXT={privacy:{title:'Chính sách quyền riêng tư',body:`<h4>Home thu thập gì</h4><ul><li>Họ tên, số điện thoại (dùng để đăng nhập).</li><li>Hợp đồng thuê, tiền cọc, hoá đơn, lịch sử thanh toán.</li><li>Ảnh và ghi chú bàn giao phòng, báo hư hỏng.</li></ul><h4>Dùng để làm gì</h4><p>Chỉ để quản lý việc thuê nhà: lập hợp đồng, thu tiền, sửa chữa, bàn giao. Không bán, không quảng cáo.</p><h4>Ai xem được</h4><p>Chủ nhà xem toàn bộ. Quản lý chỉ xem phòng mình phụ trách. Khách thuê chỉ xem hồ sơ của mình.</p><h4>Lưu ở đâu, bao lâu</h4><p>Lưu mã hoá trên máy chủ Supabase ở Singapore, sao lưu hằng ngày. Hợp đồng và hoá đơn giữ theo thời hạn pháp luật yêu cầu; dữ liệu khác xoá khi xoá tài khoản.</p><h4>Quyền của bạn</h4><p>Xem, sửa thông tin; đổi mật khẩu; yêu cầu xoá tài khoản ngay trong app (Tài khoản của tôi → Xoá tài khoản).</p><h4>Liên hệ</h4><p>Liên hệ chủ nhà hoặc quản lý đã cấp tài khoản cho bạn.</p>`},terms:{title:'Điều khoản sử dụng',body:`<h4>Tài khoản</h4><p>Tài khoản do chủ nhà hoặc quản lý cấp. Bạn giữ bí mật mật khẩu và đổi mật khẩu sau lần đăng nhập đầu.</p><h4>Thông tin</h4><p>Bạn cung cấp thông tin đúng sự thật. Xác nhận thanh toán, bàn giao, ký hợp đồng trong app có giá trị ghi nhận giữa các bên.</p><h4>Ngừng sử dụng</h4><p>Tài khoản có thể bị tạm khoá khi hết hợp đồng hoặc vi phạm. Bạn có thể yêu cầu xoá tài khoản bất cứ lúc nào.</p>`}};
function openLegal(kind){const doc=LEGAL_TEXT[kind];if(!doc)return;const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.style.zIndex=60;overlay.innerHTML=`<div class="modal-sheet legal-sheet"><span class="legal-draft">Bản nháp · cần luật sư xem lại</span><div class="modal-head">${doc.title}</div>${doc.body}<div class="modal-actions"><button type="button" class="save" data-close>Đóng</button></div></div>`;appendToPhone(overlay);overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());overlay.addEventListener('click',event=>{if(event.target===overlay)overlay.remove()})}
function readDeleteRequests(){try{const data=JSON.parse(localStorage.getItem('homeDeleteRequests')||'{}');return data&&typeof data==='object'?data:{}}catch{return{}}}
function saveDeleteRequests(all){localStorage.setItem('homeDeleteRequests',JSON.stringify(all))}
function requestAccountDeletion(user,done){const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.style.zIndex=60;overlay.innerHTML=`<div class="modal-sheet"><div class="modal-head">Xoá tài khoản?</div><p class="confirm-text">Yêu cầu sẽ được gửi cho chủ nhà. Chủ nhà xoá trong vòng 7 ngày.</p><ul class="note" style="padding-left:18px;margin:8px 0"><li>Sau khi xoá, bạn không đăng nhập được nữa.</li><li>Hợp đồng, hoá đơn đã có vẫn được lưu theo quy định pháp luật.</li>${user.role==='tenant'?'<li>Nếu còn đang thuê, cần báo trả phòng trước khi xoá.</li>':''}</ul><div class="modal-actions"><button type="button" data-cancel>Không</button><button type="button" class="save" data-ok style="background:#b3261e">Gửi yêu cầu xoá</button></div></div>`;appendToPhone(overlay);overlay.querySelector('[data-cancel]').addEventListener('click',()=>overlay.remove());overlay.querySelector('[data-ok]').addEventListener('click',()=>{const all=readDeleteRequests();all[user.key]={key:user.key,name:user.fullName||user.name,role:user.role,room:user.room||'',house:user.room?propertyIdForRoom(user.room):'',at:new Date().toLocaleString('vi-VN')};saveDeleteRequests(all);const list=readUsers(),target=list.find(item=>item.key===user.key);if(target){logUserChange(target,'Gửi yêu cầu xoá tài khoản');saveUsers(list)}overlay.remove();if(done)done()})}
function cancelAccountDeletion(key){const all=readDeleteRequests();if(!all[key])return;delete all[key];saveDeleteRequests(all);const list=readUsers(),target=list.find(item=>item.key===key);if(target){logUserChange(target,'Huỷ yêu cầu xoá tài khoản');saveUsers(list)}}
function processDeleteRequest(key){const request=readDeleteRequests()[key],user=readUsers().find(item=>item.key===key);if(!request)return;const overlay=document.createElement('div');overlay.className='modal-overlay';const close=()=>overlay.remove(),refresh=()=>{refreshUserAccounts();setAccount(document.getElementById('accountSelect').value)};let blocker='';if(!user||user.status==='Đã xoá'){const all=readDeleteRequests();delete all[key];saveDeleteRequests(all);refresh();return}if(user.role==='tenant'&&tenantHasActiveLease(user))blocker=`${escapeHTML(user.name)} còn hợp đồng ở ${escapeHTML(user.room)}. Làm trả phòng và hoàn cọc trước, rồi mới xoá tài khoản.`;if(user.role==='manager'&&managerRooms(user.name).length)blocker=`${escapeHTML(user.name)} còn phụ trách phòng ${escapeHTML(managerRooms(user.name).join(', '))}. Chuyển phòng cho quản lý khác trước, rồi mới xoá.`;overlay.innerHTML=`<div class="modal-sheet"><div class="modal-head">Xoá tài khoản · ${escapeHTML(user.fullName||user.name)}</div><p class="confirm-text">Gửi yêu cầu lúc ${escapeHTML(request.at)}.</p>${blocker?`<p class="user-alert">${blocker}</p><div class="modal-actions"><button type="button" data-cancel>Đóng</button><button type="button" class="save" data-open>Mở tài khoản</button></div>`:`<p class="note">Tài khoản sẽ chuyển sang "Đã xoá", không đăng nhập được nữa. Hợp đồng, hoá đơn cũ vẫn giữ.</p><div class="modal-actions"><button type="button" data-cancel>Huỷ</button><button type="button" class="save" data-ok style="background:#b3261e">Xoá tài khoản</button></div>`}</div>`;appendToPhone(overlay);overlay.querySelector('[data-cancel]').addEventListener('click',close);overlay.querySelector('[data-open]')?.addEventListener('click',()=>{close();go('users');openUserSheet(key)});overlay.querySelector('[data-ok]')?.addEventListener('click',()=>{const list=readUsers(),target=list.find(item=>item.key===key);if(target){target.status='Đã xoá';logUserChange(target,'Xoá tài khoản theo yêu cầu của người dùng');saveUsers(list)}const all=readDeleteRequests();delete all[key];saveDeleteRequests(all);close();refresh()})}
const collectWorkItemsDeleteBase=collectWorkItems;
collectWorkItems=function(){const items=collectWorkItemsDeleteBase(),scope=workScope();if(scope.role!=='owner')return items;Object.values(readDeleteRequests()).forEach(request=>items.push({type:'user',house:request.house||undefined,room:request.room||undefined,title:'Xoá tài khoản: '+request.name+(request.room?' · '+request.room:''),sub:({manager:'Quản lý',tenant:'Khách thuê'}[request.role]||'')+' · gửi yêu cầu '+String(request.at).split(' ').pop(),time:parseViTime(request.at),actions:[{label:'Xử lý',run:()=>processDeleteRequest(request.key)}],target:{type:'user',key:request.key}}));return items};
function signOut(){localStorage.setItem('homeSignedOut','1');document.querySelectorAll('.modal-overlay').forEach(overlay=>overlay.remove());renderLoginScreen()}
function maybeNudgePassword(){const key=sessionStorage.getItem('homePwNudge');if(!key)return;sessionStorage.removeItem('homePwNudge');if(key!==document.getElementById('accountSelect').value)return;openMyAccount(true)}
function markPasswordDot(){const key=document.getElementById('accountSelect')?.value,record=passwordRecord(key),need=!record||!record.self;document.querySelectorAll('.phone .head .app-logo').forEach(logo=>{logo.classList.toggle('pw-dot',need);logo.title='Tài khoản của tôi'})}
function openMyAccount(nudge){const key=document.getElementById('accountSelect').value,user=accountByKey(key);if(!user)return;const record=passwordRecord(key),own=record&&record.self,roleName={owner:'Chủ nhà',manager:'Quản lý',tenant:'Khách thuê'}[user.role],overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet" novalidate><div class="modal-head">Tài khoản của tôi</div>${nudge?`<p class="user-alert">${user.role==='owner'?'Anh đang dùng mật khẩu mặc định. Nên đổi sang mật khẩu riêng ngay bây giờ.':'Anh/chị đang dùng mật khẩu do người tạo tài khoản đặt. Nên đổi sang mật khẩu riêng ngay bây giờ.'}</p>`:''}<div class="user-info-row"><span>Họ tên</span><strong>${escapeHTML(user.fullName||user.name)}</strong></div><div class="user-info-row"><span>Vai trò</span><strong>${roleName}${user.room?' · '+escapeHTML(user.room):''}</strong></div><div class="user-info-row"><span>Tên đăng nhập</span><strong>${escapeHTML(user.phone||'Chưa có số điện thoại')}</strong></div><div class="user-info-row"><span>Mật khẩu</span><strong>${own?'Tự đặt · '+escapeHTML(record.at):record?'Do '+escapeHTML(record.by||'người tạo')+' đặt':user.role==='owner'?'Mật khẩu mặc định':'Mật khẩu ban đầu'}</strong></div><div class="user-section-title">Đổi mật khẩu</div><label>Mật khẩu hiện tại</label><input name="current" type="password" autocomplete="current-password"><label>Mật khẩu mới (ít nhất 6 ký tự)</label><input name="next" type="password" autocomplete="new-password"><label>Nhập lại mật khẩu mới</label><input name="again" type="password" autocomplete="new-password"><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-cancel>${nudge?'Để sau':'Đóng'}</button><button type="submit" class="save">Đổi mật khẩu</button></div><button type="button" class="user-lock" data-app-feedback>Góp ý về app</button><button type="button" class="user-lock" data-signout>Đăng xuất</button><div class="delete-box">${user.role==='owner'?'<p>Tài khoản chủ nhà giữ toàn bộ dữ liệu nên không xoá trong app. Cần xoá thì liên hệ người hỗ trợ kỹ thuật.</p>':readDeleteRequests()[key]?`<p>Đã gửi yêu cầu xoá lúc ${escapeHTML(readDeleteRequests()[key].at)}. Chủ nhà sẽ xử lý trong vòng 7 ngày.</p><button type="button" class="user-delete" data-cancel-delete>Huỷ yêu cầu xoá</button>`:'<button type="button" class="user-delete" data-delete-account>Xoá tài khoản</button>'}</div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form'),error=text=>{const box=form.querySelector('.user-error');box.textContent=text;box.hidden=false};overlay.querySelector('[data-cancel]').addEventListener('click',()=>overlay.remove());overlay.querySelector('[data-signout]').addEventListener('click',signOut);overlay.querySelector('[data-app-feedback]').addEventListener('click',()=>{overlay.remove();openAppFeedback(user)});overlay.querySelector('[data-delete-account]')?.addEventListener('click',()=>requestAccountDeletion(user,()=>{overlay.remove();openMyAccount(false)}));overlay.querySelector('[data-cancel-delete]')?.addEventListener('click',()=>{cancelAccountDeletion(key);overlay.remove();openMyAccount(false)});form.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(form),current=String(data.get('current')||''),next=String(data.get('next')||'').trim(),again=String(data.get('again')||'').trim(),okNow=window.HOME_REAL?await window.HOME_DB.verifyPassword(current):current===userPassword(key);if(!okNow)return error('Mật khẩu hiện tại chưa đúng.');if(next.length<6)return error('Mật khẩu mới cần ít nhất 6 ký tự.');if(next===current)return error('Mật khẩu mới phải khác mật khẩu hiện tại.');if(next!==again)return error('Hai lần nhập mật khẩu mới chưa giống nhau.');setUserPassword(key,next,user.name,true);const list=readUsers(),target=list.find(item=>item.key===key);if(target){logUserChange(target,'Tự đổi mật khẩu');saveUsers(list)}form.innerHTML='<div class="modal-head">Đã đổi mật khẩu</div><p class="pw-box">Lần sau anh/chị đăng nhập bằng <b>'+escapeHTML(user.phone||'')+'</b> và mật khẩu mới.</p><div class="modal-actions"><button type="button" class="save" data-close>Xong</button></div>';form.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());markPasswordDot()})}
