function markConfirmedSeedProfiles(){Object.entries(tenantProfiles).forEach(([room,profile])=>{if(!profile.overdue||!/^Quá hạn \d+ ngày$/.test(profile.dueStatus||''))return;const [d,m,y]=String(profile.dueDate||'').split('/').map(Number);if(!y)return;const days=Math.floor((Date.now()-new Date(y,m-1,d).getTime())/86400000);if(days>0)profile.dueStatus='Quá hạn '+days+' ngày'});let states={};try{states=JSON.parse(localStorage.getItem('homeActionStates')||'{}')}catch{}financeSeed.forEach(seed=>{const profile=tenantProfiles[seed.room];if(seed.kind!=='income'||seed.status==='Đã xác nhận'||!profile||profile.seedConfirmed||/Đã trả phòng/.test(profile.contractStatus||''))return;let state=Object.entries(states).find(([key])=>cleanLegacyTitle(key).startsWith(seed.key))?.[1];if(!state){const paid=(readTenantEventsSafe()[seed.room]||[]).filter(event=>event.kind==='payment'&&event.status==='Đã xác nhận').pop();if(paid)state={date:paid.confirmedAt?new Date(paid.confirmedAt).toLocaleDateString('vi-VN'):String(paid.date||'').split(' ').pop()}}if(!state)return;const label=seed.title.split(' · ').pop(),amount=amountForHouse(seed.amount,propertyIdForRoom(seed.room)),payments=(profile.payments||[]).filter(item=>item.title!==label);payments.push({date:state.date||'',title:label,amount,status:'Đã xác nhận'});tenantProfiles[seed.room]={...profile,seedConfirmed:true,dueAmount:0,overdue:false,lastPaid:seed.amount,dueStatus:'Đã thanh toán',dueNote:label+' đã được xác nhận'+(state.date?' ngày '+state.date:''),payments}})}
