{const base=collectWorkItems;collectWorkItems=function(...args){const items=base.apply(this,args);items.forEach(item=>{if(item.type!=='payment'||!item.room||!(item.actions||[]).some(a=>a.label==='Xác nhận'))return;const event=(readTenantEventsSafe()[item.room]||[]).filter(e=>e.kind==='payment'&&(!e.status||e.status==='Chờ xử lý')).pop();if(event&&!item.actions.some(a=>a.label==='Từ chối'))item.actions.push({label:'Từ chối',confirmWrapped:true,run:()=>rejectTenantPayment(item.room,event.id)})});return items}}
