function bigExpenseLimit(house){const home=readProperties().find(h=>h.id===house);if(home&&home.bigExpenseLimit!=null&&home.bigExpenseLimit!=='')return Number(home.bigExpenseLimit);return home?.currency==='VND'?5000000:200}
