function saveSpendRequests(list){localStorage.setItem('homeSpendRequests',JSON.stringify(list))}
function updateSpendRequest(id,changes){const list=readSpendRequests(),item=list.find(r=>r.id===id);if(!item)return null;Object.assign(item,changes);saveSpendRequests(list);return item}
function myApprovedRequests(){const [role,name]=document.getElementById('accountSelect').value.split('|'),house=readProperty().id;return readSpendRequests().filter(r=>r.by===name&&r.house===house&&r.status==='Đã duyệt')}
function showReceipt(record){const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<div class="modal-sheet"><div class="modal-head">Hoá đơn · ${escapeHTML(record.name||'')}</div><img src="${record.receipt}" alt="Ảnh hoá đơn" style="width:100%;border-radius:12px"><p class="note">${escapeHTML(amountForHouse(record.amount,record.propertyId))} · ghi bởi ${escapeHTML(record.createdBy||'')}</p><div class="modal-actions"><button type="button" data-close>Đóng</button></div></div>`;appendToPhone(overlay);overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove())}
