function decideSpendRequest(id,approve){const req=readSpendRequests().find(r=>r.id===id);if(!req)return;const unit=readProperties().find(h=>h.id===req.house)?.currency==='VND'?'₫':'$',overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet" novalidate><div class="modal-head">${approve?'Duyệt':'Từ chối'} đề xuất chi</div><p class="note">${escapeHTML(req.title)} · dự kiến ${escapeHTML(amountForHouse(req.amount,req.house))} · ${escapeHTML(req.by)}${req.room?' · '+escapeHTML(req.room):''}${req.note?' · '+escapeHTML(req.note):''}</p>${approve?`<label>Số tiền tối đa được chi (${unit})</label><input name="max" type="number" min="1" step="any" value="${escapeHTML(String(req.amount))}">`:'<label>Lý do</label><textarea name="reason" rows="2"></textarea>'}<p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-cancel>Huỷ</button><button type="submit" class="save${approve?'':' danger'}">${approve?'Duyệt':'Từ chối'}</button></div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form');form.querySelector('[data-cancel]').addEventListener('click',()=>overlay.remove());form.addEventListener('submit',e=>{e.preventDefault();const err=form.querySelector('.user-error'),now=new Date().toLocaleString('vi-VN');if(approve){const max=Number(form.max.value);if(!(max>0)){err.textContent='Nhập số tiền tối đa.';err.hidden=false;return}updateSpendRequest(id,{status:'Đã duyệt',maxAmount:max,decidedBy:currentActorName(),decidedAt:now})}else{const reason=form.reason.value.trim();if(!reason){err.textContent='Ghi lý do để quản lý biết.';err.hidden=false;return}updateSpendRequest(id,{status:'Từ chối',reason,decidedBy:currentActorName(),decidedAt:now})}overlay.remove();try{renderManagementOverview()}catch{}})}
