function openComplaintForm(){const account=document.getElementById('accountSelect').value,[role,name,room]=account.split('|');if(role!=='tenant')return;const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet" novalidate><div class="modal-head">Góp ý / khiếu nại · ${escapeHTML(room)}</div><p class="note">Nội dung gửi thẳng cho chủ nhà. Quản lý không xem được.</p><label>Nội dung</label><textarea name="text" rows="4" maxlength="600" placeholder="Ví dụ: quản lý hẹn sửa 3 ngày chưa tới"></textarea><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-cancel>Huỷ</button><button type="submit" class="save">Gửi chủ nhà</button></div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form');form.querySelector('[data-cancel]').addEventListener('click',()=>overlay.remove());form.addEventListener('submit',e=>{e.preventDefault();const text=form.text.value.trim();if(!text){const err=form.querySelector('.user-error');err.textContent='Ghi nội dung góp ý.';err.hidden=false;return}const list=readComplaints();list.push({id:'K'+Date.now().toString(36),room,house:propertyIdForRoom(room),tenantKey:account,tenantName:name,text,at:new Date().toLocaleString('vi-VN'),status:'Chờ chủ nhà'});saveComplaints(list);overlay.remove();renderTenantComplaints()});setTimeout(()=>form.text.focus(),50)}
function replyComplaint(id){const item=readComplaints().find(c=>c.id===id);if(!item)return;const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet" novalidate><div class="modal-head">Trả lời góp ý · ${escapeHTML(item.room)}</div><p class="note">${escapeHTML(item.tenantName)} · ${escapeHTML(String(item.at).split(' ').pop())}: “${escapeHTML(item.text)}”</p><label>Trả lời khách</label><textarea name="reply" rows="3"></textarea><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-cancel>Huỷ</button><button type="submit" class="save">Gửi và đóng</button></div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form');form.querySelector('[data-cancel]').addEventListener('click',()=>overlay.remove());form.addEventListener('submit',e=>{e.preventDefault();const reply=form.reply.value.trim();if(!reply){const err=form.querySelector('.user-error');err.textContent='Ghi câu trả lời cho khách.';err.hidden=false;return}const list=readComplaints(),c=list.find(x=>x.id===id);c.status='Đã trả lời';c.reply=reply;c.repliedBy=currentActorName();c.repliedAt=new Date().toLocaleString('vi-VN');saveComplaints(list);overlay.remove();try{renderManagementOverview()}catch{}});setTimeout(()=>form.reply.focus(),50)}
function renderTenantComplaints(){const account=document.getElementById('accountSelect').value,[role,,room]=account.split('|'),portal=document.getElementById('tenantPortal');document.getElementById('tenantComplaints')?.remove();if(role!=='tenant'||!portal)return;const actions=[...portal.querySelectorAll('.tenant-actions')].pop();if(actions&&!portal.querySelector('[data-complaint-open]'))actions.insertAdjacentHTML('beforeend','<button type="button" data-complaint-open>Góp ý / khiếu nại</button>');const mine=readComplaints().filter(c=>c.tenantKey===account).slice(-3).reverse();if(!mine.length||!actions)return;actions.insertAdjacentHTML('afterend',`<div id="tenantComplaints" class="tenant-card"><div class="tenant-title">Góp ý của anh/chị</div>${mine.map(c=>`<div class="complaint-item"><small>${escapeHTML(String(c.at).split(' ').pop())} · ${escapeHTML(c.status)}</small><p>${escapeHTML(c.text)}</p>${c.reply?`<p class="complaint-reply"><b>${escapeHTML(c.repliedBy||'Chủ nhà')}:</b> ${escapeHTML(c.reply)}</p>`:''}</div>`).join('')}</div>`)}
