// Việc cần xử lý: góp ý (chỉ chủ nhà), đề xuất chi; nút xem hoá đơn
{const base=collectWorkItems;collectWorkItems=function(...args){const items=base.apply(this,args),scope=workScope();if(!['owner','manager'].includes(scope.role))return items;if(scope.role==='owner')readComplaints().forEach(c=>{if(c.status!=='Chờ chủ nhà'||!scope.houseOk(c.house))return;items.push({type:'complaint',house:c.house,room:c.room,title:c.room+' · góp ý của '+c.tenantName,sub:c.text,time:parseViTime(c.at),actions:[{label:'Trả lời',run:()=>replyComplaint(c.id)}],target:{type:'room',room:c.room}})});readSpendRequests().forEach(r=>{if(!scope.houseOk(r.house))return;const base2={type:'spend',house:r.house,room:r.room||'',time:parseViTime(r.decidedAt||r.at),target:{type:'finance',text:r.title}};if(scope.role==='owner'&&r.status==='Chờ duyệt')items.push({...base2,title:'Đề xuất chi: '+r.title,sub:'Dự kiến '+amountForHouse(r.amount,r.house)+' · '+r.by+(r.room?' · '+r.room:' · chi chung')+(r.note?' · '+r.note:''),actions:[{label:'Duyệt',confirmWrapped:true,run:()=>decideSpendRequest(r.id,true)},{label:'Từ chối',confirmWrapped:true,run:()=>decideSpendRequest(r.id,false)}]});if(scope.role==='manager'&&r.by===scope.name){if(r.status==='Chờ duyệt')items.push({...base2,title:'Đề xuất chi: '+r.title,sub:'Chờ chủ nhà duyệt · dự kiến '+amountForHouse(r.amount,r.house),actions:[]});if(r.status==='Đã duyệt')items.push({...base2,title:'Đã được duyệt chi: '+r.title,sub:'Tối đa '+amountForHouse(r.maxAmount,r.house)+' · chi xong thì ghi chi phí kèm hoá đơn',actions:[{label:'Ghi chi phí',run:()=>{go('finance',document.querySelector('.tab[data-id="finance"]'));openExpenseWithRequest(r.id)}}]});if(r.status==='Từ chối'&&!r.seen)items.push({...base2,title:'Đề xuất chi bị từ chối: '+r.title,sub:'Lý do: '+(r.reason||''),actions:[{label:'Đã xem',run:()=>{updateSpendRequest(r.id,{seen:true});try{renderManagementOverview()}catch{}}}]})}});items.forEach(item=>{if(item.type!=='expense')return;const rec=expenseRecordForItem(item);if(rec&&!(item.actions||[]).some(a=>a.label==='Hoá đơn'))item.actions=[...(item.actions||[]),{label:'Hoá đơn',confirmWrapped:true,run:()=>showReceipt(rec)}]});return items}}
{const base=collectFinanceItems;collectFinanceItems=function(...args){const items=base.apply(this,args);items.forEach(item=>{if(item.kind!=='expense')return;const rec=expenseRecordForItem(item);if(rec&&!(item.actions||[]).some(a=>a.label==='Hoá đơn'))item.actions=[...(item.actions||[]),{label:'Hoá đơn',confirmWrapped:true,run:()=>showReceipt(rec)}]});return items}}
