{const base=collectWorkItems;collectWorkItems=function(...args){const items=base.apply(this,args),scope=workScope();if(!['owner','manager'].includes(scope.role))return items;collectRoomRecords(true).records.filter(r=>r.status==='Đang thuê'&&scope.houseOk(r.house)&&scope.roomOk(r.code)).forEach(r=>{const room=r.code;if(!roomTenantUser(room)||vacatedRoom(room)||!meterServices(room).length)return;const period=utilityPeriodDue(room);if(!period)return;items.push({type:'payment',house:r.house,room,title:room+': nhập chỉ số điện nước '+monthLabel(period).toLocaleLowerCase(),sub:'Theo đồng hồ · '+meterServices(room).map(sv=>UTIL_LABEL[sv][0].toLowerCase()+' cũ '+lastMeterReading(room,sv)).join(', '),time:Date.now(),actions:[{label:'Nhập chỉ số',run:()=>openMeterForm(room,period)}],target:{type:'room',room}})});return items}}
