{const base=computeSettlement;computeSettlement=function(houseId,month,...rest){const data=base.call(this,houseId,month,...rest);if(!data||!data.managers)return data;const period=settlementPeriod(houseId),round=v=>roundForHouse(v,houseId),deposits=depositReceipts(houseId).filter(d=>period(d.time)===month),refunds=Object.values(readCheckouts()).filter(r=>r.house===houseId&&r.status==='Đã hoàn cọc'&&r.holder&&r.holder!==ownerName()&&period(parseViTime(r.tenantConfirmedAt))===month&&depositRemittedFlow(r.room,r.tenantKey));const names=new Set([...deposits.map(d=>d.holder),...refunds.map(r=>r.holder)]);names.forEach(name=>{if(!data.managers[name])data.managers[name]={rooms:[],profit:0,carryIn:0,base:0,share:0,carryOut:0,collected:0,paid:0,net:0,mustRemit:0};const m=data.managers[name],depositsIn=round(deposits.filter(d=>d.holder===name).reduce((s,d)=>s+d.amount,0)),refundAdvance=round(refunds.filter(r=>r.holder===name).reduce((s,r)=>s+Math.max(0,(Number(r.refund)||0)-(Number(r.ownerTransfer)||0)),0));m.depositsIn=depositsIn;m.refundAdvance=refundAdvance;m.mustRemit=round((Number(m.mustRemit)||0)+depositsIn-refundAdvance)});return data}}
