{const base=incomeEntries;incomeEntries=function(houseId,...rest){const list=base.call(this,houseId,...rest),owner=ownerName();list.forEach(e=>{if(!/Trừ cọc khi trả phòng/.test(e.label||''))return;const rec=readCheckouts()[e.room];if(rec&&depositRemittedFlow(e.room,rec.tenantKey))e.holder=owner});return list}}
// Quỹ: tiền cọc mới thu tính vào tiền của chủ nhà quản lý đang giữ (phải nộp), không còn tính là "cọc quản lý giữ"
{const base=custodySummary;custodySummary=function(houseId,...rest){const list=base.call(this,houseId,...rest),deposits=depositReceipts(houseId),managers=readRoomManagerAssignments();list.forEach(entry=>{const advance=Object.values(readCheckouts()).filter(r=>r.house===houseId&&r.status==='Đã hoàn cọc'&&r.holder===entry.name&&depositRemittedFlow(r.room,r.tenantKey)).reduce((s,r)=>s+Math.max(0,(Number(r.refund)||0)-(Number(r.ownerTransfer)||0)),0),extra=deposits.filter(d=>d.holder===entry.name).reduce((s,d)=>s+d.amount,0)-advance;entry.ownerMoney=roundForHouse((Number(entry.ownerMoney)||0)+extra,houseId);const remittedRooms=(entry.depositRooms||[]).filter(room=>depositRemittedFlow(room));if(remittedRooms.length){remittedRooms.forEach(room=>{entry.deposits-=Number(getHomeContract(room)?.deposit)||0});entry.depositRooms=entry.depositRooms.filter(room=>!remittedRooms.includes(room));entry.deposits=Math.max(0,roundForHouse(entry.deposits,houseId))}});return list}}
