const RECEIPT_VIA={transfer:'Chuyển khoản',cash:'Tiền mặt',credit:'Trừ tiền khách trả dư',hold:'Chuyển từ cọc giữ chỗ'};
function showReceiptPaper(chargeId,index){const c=readRentCharges().find(x=>x.id===chargeId),part=c&&chargeParts(c)[index];if(!part)return;const home=readProperties().find(h=>h.id===c.house)||{},money=v=>amountForHouse(v,c.house),paidBefore=chargeParts(c).slice(0,index+1).reduce((s,p)=>s+(Number(p.amount)||0),0),total=Number(c.originalAmount??c.amount)||0,left=Math.max(0,roundForHouse(total-paidBefore,c.house)),rows=[['Số biên lai',receiptNo(c,index)],['Phòng',c.room],['Khách thuê',c.tenantName||''],['Khoản thu',c.title||''],c.period?['Kỳ',c.period.split('-').reverse().join('/')]:null,['Thời gian thu',part.at||''],['Người thu',part.by||''],RECEIPT_VIA[part.via]?['Hình thức',RECEIPT_VIA[part.via]]:null,left>0.005?['Còn lại của khoản này',money(left)]:null].filter(Boolean);const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<div class="modal-sheet"><div class="modal-head">Biên lai thu tiền</div><div class="receipt-paper"><h4>${escapeHTML(home.name||'Home')}</h4>${home.address&&home.address!==home.name?`<div class="receipt-sub">${escapeHTML(home.address)}</div>`:''}${rows.map(([a,b])=>`<div class="receipt-row"><span>${escapeHTML(a)}</span><span>${escapeHTML(String(b))}</span></div>`).join('')}<div class="receipt-total">${money(part.amount)}</div><div class="receipt-sub">Đã nhận đủ số tiền trên. Biên lai tạo tự động bởi app Home.</div></div><div class="modal-actions"><button type="button" data-close>Đóng</button><button type="button" class="primary" data-print>In / lưu PDF</button></div></div>`;appendToPhone(overlay);overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());overlay.querySelector('[data-print]').addEventListener('click',()=>window.print())}
function showReceiptList(title,list){const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<div class="modal-sheet"><div class="modal-head">${escapeHTML(title)}</div><div class="receipt-list">${list.length?list.map(r=>`<button type="button" data-receipt="${escapeHTML(r.charge.id)}" data-receipt-index="${r.index}"><b>${escapeHTML(r.no)}</b> · ${escapeHTML(amountForHouse(r.part.amount,r.charge.house))}<br><small>${escapeHTML(r.charge.title||'')} · ${escapeHTML(r.charge.tenantName||'')} · ${escapeHTML(r.part.at||'')}</small></button>`).join(''):'<p class="note">Chưa có biên lai nào.</p>'}</div><div class="modal-actions"><button type="button" data-close>Đóng</button></div></div>`;appendToPhone(overlay);overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove())}
document.addEventListener('click',event=>{const b=event.target.closest('[data-receipt]');if(b){showReceiptPaper(b.dataset.receipt,Number(b.dataset.receiptIndex)||0);return}const room=event.target.closest('[data-room-receipts]');if(room){const code=room.dataset.roomReceipts;showReceiptList('Biên lai · '+code,receiptsFor(c=>c.room===code))}});
// Khách: thẻ "Biên lai của tôi"
function renderTenantReceipts(){const account=document.getElementById('accountSelect').value,[role]=account.split('|'),portal=document.getElementById('tenantPortal'),cur=document.getElementById('tenantReceipts');if(role!=='tenant'||!portal){cur?.remove();return}const list=receiptsFor(c=>c.tenantKey===account),sig=account+'|'+list.map(r=>r.no).join(',');if(cur&&cur.dataset.sig===sig)return;cur?.remove();if(!list.length)return;const anchor=document.getElementById('tenantComplaints')||[...portal.querySelectorAll('.tenant-actions')].pop();if(!anchor)return;anchor.insertAdjacentHTML('afterend',`<div id="tenantReceipts" class="tenant-card receipt-list" data-sig="${escapeHTML(sig)}"><div class="tenant-title">Biên lai của tôi <span class="tenant-asset-count">${list.length}</span></div>${list.slice(0,4).map(r=>`<button type="button" data-receipt="${escapeHTML(r.charge.id)}" data-receipt-index="${r.index}"><b>${escapeHTML(amountForHouse(r.part.amount,r.charge.house))}</b> · ${escapeHTML(r.charge.title||'')}<br><small>${escapeHTML(r.no)} · ${escapeHTML(r.part.at||'')}</small></button>`).join('')}</div>`)}
{const base=renderTenantConfirmations;renderTenantConfirmations=function(...args){const result=base.apply(this,args);try{renderTenantReceipts()}catch{}return result}}
setTimeout(()=>{try{renderTenantReceipts()}catch{}},0);
// Chủ nhà / quản lý: nút "Biên lai đã thu" trong chi tiết phòng
new MutationObserver(()=>{document.querySelectorAll('.phone .rd-sheet').forEach(sheet=>{if(sheet.querySelector('[data-room-receipts]'))return;const code=(sheet.querySelector('.modal-head')?.textContent.match(/P\.\d+/)||[])[0];if(!code)return;const n=receiptsFor(c=>c.room===code).length;if(!n)return;const actions=sheet.querySelector('.modal-actions');(actions||sheet).insertAdjacentHTML(actions?'beforebegin':'beforeend',`<button type="button" class="link-btn" data-room-receipts="${escapeHTML(code)}">Biên lai đã thu (${n})</button>`)})}).observe(document.querySelector('.phone')||document.body,{childList:true,subtree:true});

// ===== Đợt 3: (1) Cọc giữ chỗ (mặc định 7 ngày) =====
const HOLD_DAYS=7;
function readHolds(){try{const v=JSON.parse(localStorage.getItem('homeRoomHolds')||'[]');return Array.isArray(v)?v:[]}catch{return []}}
function saveHolds(list){localStorage.setItem('homeRoomHolds',JSON.stringify(list))}
function activeHold(room){return readHolds().find(h=>h.room===room&&['Đang giữ','Đã ký hợp đồng'].includes(h.status))||null}
function holdExpired(h){return h.status==='Đang giữ'&&Date.now()>dayStart(h.until)+DAY_MS-1}
function updateHold(id,patch,history,actor){const list=readHolds(),h=list.find(x=>x.id===id);if(!h)return;Object.assign(h,patch);saveHolds(list);if(history)appendRoomHistory(h.room,{kind:'contract',title:history,detail:h.name+' · '+amountForHouse(h.amount,h.house),actor:actor||currentActorName()});try{renderManagementOverview()}catch{}document.querySelectorAll('.phone .rd-sheet [data-hold-box]').forEach(b=>b.replaceWith(holdBox(h.room)))}
function openHoldForm(room){const house=propertyIdForRoom(room),overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet"><div class="modal-head">Nhận cọc giữ chỗ · ${escapeHTML(room)}</div><label>Tên khách</label><input name="name" required><label>Số điện thoại</label><input name="phone" inputmode="tel" required><label>Số tiền giữ chỗ (${readProperties().find(h=>h.id===house)?.currency==='VND'?'₫':'$'})</label><input name="amount" type="number" min="0" step="any" required><label>Giữ trong (ngày)</label><input name="days" type="number" min="1" max="60" value="${HOLD_DAYS}"><p class="note">Khách ký hợp đồng trong hạn thì khoản này trừ vào tiền cọc. Hết hạn mà khách không đến thì mất khoản giữ chỗ (ghi vào thu).</p><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-close>Huỷ</button><button class="primary">Lưu</button></div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form'),err=form.querySelector('.user-error');overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());form.addEventListener('submit',e=>{e.preventDefault();const name=form.name.value.trim(),phone=form.phone.value.trim(),amount=Number(form.amount.value),days=Math.max(1,Number(form.days.value)||HOLD_DAYS);if(name.length<2||phone.replace(/\D/g,'').length<8||!(amount>0)){err.hidden=false;err.textContent='Nhập đủ tên, số điện thoại và số tiền.';return}if(activeHold(room)){err.hidden=false;err.textContent='Phòng này đang có người giữ chỗ.';return}const now=new Date(),list=readHolds(),h={id:'H'+Date.now().toString(36),room,house,name,phone,amount:roundForHouse(amount,house),createdAt:now.toLocaleString('vi-VN'),until:dayStart()+days*DAY_MS,by:currentActorName(),status:'Đang giữ'};list.push(h);saveHolds(list);appendRoomHistory(room,{kind:'contract',title:'Nhận cọc giữ chỗ của '+name,detail:amountForHouse(h.amount,house)+' · giữ đến '+viDate(h.until),actor:h.by,amount:h.amount});overlay.remove();document.querySelectorAll('.phone .rd-sheet [data-hold-box]').forEach(b=>b.replaceWith(holdBox(room)));try{renderManagementOverview()}catch{}});setTimeout(()=>form.name.focus(),50)}
function holdActions(h,role){const out=[{label:'Gia hạn '+HOLD_DAYS+' ngày',run:()=>updateHold(h.id,{until:Math.max(dayStart(),dayStart(h.until))+HOLD_DAYS*DAY_MS},'Gia hạn giữ chỗ '+HOLD_DAYS+' ngày')},{label:'Khách không đến · mất cọc',run:()=>appConfirm('Khách không đến, mất cọc giữ chỗ?',h.name+' · '+amountForHouse(h.amount,h.house)+' ghi vào khoản thu của căn.','Mất cọc',()=>updateHold(h.id,{status:'Mất cọc giữ chỗ',closedAt:new Date().toLocaleString('vi-VN'),closedBy:currentActorName()},'Khách không đến, mất cọc giữ chỗ'))}];if(role==='owner')out.push({label:'Trả lại khách',run:()=>appConfirm('Trả lại tiền giữ chỗ?',h.name+' · '+amountForHouse(h.amount,h.house)+' (chủ nhà đồng ý).','Trả lại',()=>updateHold(h.id,{status:'Đã trả lại',closedAt:new Date().toLocaleString('vi-VN'),closedBy:currentActorName()},'Chủ nhà đồng ý trả lại tiền giữ chỗ'))});return out}
function holdBox(room){const box=document.createElement('div');box.dataset.holdBox=room;box.className='tenant-card';const role=document.getElementById('accountSelect').value.split('|')[0],h=activeHold(room),card=cardForRoom(room),status=card?getRoomCardRecord(card).status:'';if(!['owner','manager'].includes(role)||(!h&&status!=='Trống')){box.hidden=true;return box}if(!h){box.innerHTML='<button type="button" data-hold-new>Nhận cọc giữ chỗ</button>';box.querySelector('button').addEventListener('click',()=>openHoldForm(room));return box}box.innerHTML=`<div class="tenant-title">Đang giữ chỗ</div><p class="note">${escapeHTML(h.name)} · ${escapeHTML(h.phone)} · ${escapeHTML(amountForHouse(h.amount,h.house))}<br>${h.status==='Đã ký hợp đồng'?'Đã lập hợp đồng, sẽ trừ vào tiền cọc':(holdExpired(h)?'Đã hết hạn ':'Giữ đến ')+viDate(h.until)} · nhận bởi ${escapeHTML(h.by)}</p>`;if(h.status==='Đang giữ')holdActions(h,role).forEach(a=>{const b=document.createElement('button');b.type='button';b.textContent=a.label;b.addEventListener('click',a.run);box.append(b)});return box}
new MutationObserver(()=>{document.querySelectorAll('.phone .rd-sheet').forEach(sheet=>{if(sheet.querySelector('[data-hold-box]'))return;const code=(sheet.querySelector('.modal-head')?.textContent.match(/P\.\d+/)||[])[0];if(!code)return;const actions=sheet.querySelector('.modal-actions');(actions||sheet)[actions?'before':'append'](holdBox(code))})}).observe(document.querySelector('.phone')||document.body,{childList:true,subtree:true});
// Lập hợp đồng trên phòng đang giữ chỗ → đánh dấu, rồi trừ vào khoản cọc khi khoản cọc được tạo
{const base=saveHomeContract;saveHomeContract=function(room,contract,...rest){const result=base.call(this,room,contract,...rest);try{const h=readHolds().find(x=>x.room===room&&x.status==='Đang giữ');if(h&&contract&&contract.createdAt&&!['Đã huỷ','Từ chối'].includes(contract.status))updateHold(h.id,{status:'Đã ký hợp đồng',contractTenant:contract.tenantName||''},'Hợp đồng lập cho phòng đang giữ chỗ · sẽ trừ vào tiền cọc')}catch{}return result}}
function applyHoldsToDeposits(){let applied=false;readHolds().filter(h=>h.status==='Đã ký hợp đồng').forEach(h=>{const charge=readRentCharges().filter(c=>c.room===h.room&&c.kind==='deposit'&&c.status==='Chưa thu'&&parseViTime(c.createdAt)>=parseViTime(h.createdAt)-60000).pop();if(!charge)return;if((charge.parts||[]).some(p=>p.via==='hold')){updateHold(h.id,{status:'Đã trừ vào cọc'});return}const used=applyChargePayment(charge.id,h.amount,'hold');if(!used)return;applied=true;const list=readRentCharges(),c=list.find(x=>x.id===charge.id),part=c?.parts?.[c.parts.length-1];if(part){part.by=h.by;part.at=h.createdAt;if(c.status==='Đã thu')c.paidBy=h.by;localStorage.setItem('homeRentCharges',JSON.stringify(list))}const extra=roundForHouse(h.amount-used,h.house);updateHold(h.id,{status:'Đã trừ vào cọc',closedAt:new Date().toLocaleString('vi-VN'),usedAmount:used,extra:extra>0?extra:0},'Trừ cọc giữ chỗ '+amountForHouse(used,h.house)+' vào tiền cọc'+(extra>0?' · dư '+amountForHouse(extra,h.house)+' trả lại khách':''),'Tự động')});return applied}
{const base=ensureRentCharges;ensureRentCharges=function(...args){const result=base.apply(this,args);try{if(applyHoldsToDeposits())return readRentCharges()}catch{}return result}}
// Mất cọc giữ chỗ → khoản thu của căn (người nhận tiền đang giữ)
{const base=incomeEntries;incomeEntries=function(houseId,...rest){const list=base.call(this,houseId,...rest);readHolds().forEach(h=>{if(h.house===houseId&&h.status==='Mất cọc giữ chỗ')list.push({room:h.room,amount:h.amount,time:parseViTime(h.closedAt),holder:h.by,label:h.room+' · Mất cọc giữ chỗ ('+h.name+')'})});return list}}
{const base=collectFinanceItems;collectFinanceItems=function(...args){const items=base.apply(this,args),scope=workScope(),propertyId=readProperty().id||'HOME-001';readHolds().forEach(h=>{if(h.house!==propertyId||h.status!=='Mất cọc giữ chỗ'||!scope.roomOk(h.room))return;items.push({kind:'income',house:propertyId,room:h.room,title:h.room+' · Mất cọc giữ chỗ',sub:h.name+' không đến · nhận bởi '+h.by,amount:h.amount,done:true,pending:false,time:parseViTime(h.closedAt),actions:[],target:{type:'room',room:h.room}})});return items}}
// Việc cần xử lý: hết hạn giữ chỗ
{const base=collectWorkItems;collectWorkItems=function(...args){const items=base.apply(this,args),scope=workScope();if(!['owner','manager'].includes(scope.role))return items;readHolds().forEach(h=>{if(!holdExpired(h)||!scope.houseOk(h.house)||!scope.roomOk(h.room))return;items.push({type:'contract',house:h.house,room:h.room,title:h.room+': hết hạn giữ chỗ của '+h.name,sub:amountForHouse(h.amount,h.house)+' · hạn '+viDate(h.until)+' · '+h.phone,time:h.until,urgent:true,actions:holdActions(h,scope.role),target:{type:'room',room:h.room}})});return items}}

// ===== Đợt 3: (2) Tiền thuê tháng cuối khi trả phòng giữa kỳ =====
// Báo trước đủ 1 tháng: kỳ cuối tính theo số ngày ở. Đi đột ngột: tính trọn kỳ. Kỳ sau ngày trả phòng: không thu.
function lastMonthProrate(room){const lease=roomLease(room),user=roomTenantUser(room),request=moveOutRequest(room),leave=dayStart(request?parseViTime(request.date):Date.now()),rent=Number(lease.rent)||0,house=propertyIdForRoom(room),dueOf=(y,m)=>new Date(y,m,Math.min(lease.dueDay||1,new Date(y,m+1,0).getDate())).getTime();if(!user)return null;let d=new Date(leave),start=dueOf(d.getFullYear(),d.getMonth());if(start>leave)start=dueOf(d.getFullYear(),d.getMonth()-1);const sd=new Date(start),next=dueOf(sd.getFullYear(),sd.getMonth()+1),charges=readRentCharges().filter(c=>c.room===room&&c.kind==='rent'&&!c.extra&&c.tenantKey===user.key),future=charges.filter(c=>c.status==='Chưa thu'&&dayStart(c.due)>=next),notice=!!request&&!checkoutForfeit(room),charge=charges.filter(c=>dayStart(c.due)>=start-3*DAY_MS&&dayStart(c.due)<next).pop()||null,total=Math.round((next-start)/DAY_MS),used=Math.max(0,Math.min(total,Math.round((leave-start)/DAY_MS))),out={room,leave,start,next,total,used,rent,notice,futureIds:future.map(c=>c.id),futureAmount:roundForHouse(future.reduce((s,c)=>s+(Number(c.amount)||0),0),house),chargeId:charge?.id||'',chargePaid:charge?.status==='Đã thu',unused:0,rentRefund:0};if(notice&&charge&&used<total){out.unused=roundForHouse(rent*(total-used)/total,house);if(out.chargePaid)out.rentRefund=out.unused}if(!out.futureAmount&&!out.unused&&(out.notice||!checkoutForfeit(room)))return null;return out}
const lastMonthDraft={};
{const base=checkoutPrefill;checkoutPrefill=function(room,...rest){const lines=base.call(this,room,...rest),p=lastMonthProrate(room);lastMonthDraft[room]=p;if(!p)return lines;const less=p.futureAmount+(p.chargePaid?0:p.unused),debt=lines.find(l=>/còn nợ/i.test(l.reason));if(debt&&less>0){debt.amount=roundForHouse(debt.amount-less,propertyIdForRoom(room));if(debt.amount<=0.005)lines.splice(lines.indexOf(debt),1)}return lines}}
function lastMonthNote(p){if(!p)return '';const house=propertyIdForRoom(p.room),parts=[];if(p.unused)parts.push(`Khách báo trước đủ 1 tháng: kỳ cuối (${viDate(p.start)}–${viDate(p.next-DAY_MS)}) chỉ tính ${p.used}/${p.total} ngày ở, ${p.chargePaid?'hoàn lại khách '+amountForHouse(p.rentRefund,house)+' (đã cộng vào tiền hoàn)':'bớt '+amountForHouse(p.unused,house)+' tiền thuê kỳ cuối'}.`);else if(!p.notice)parts.push('Khách đi không báo trước đủ 1 tháng nên kỳ cuối tính trọn tháng.');if(p.futureAmount)parts.push('Không thu kỳ sau ngày trả phòng ('+amountForHouse(p.futureAmount,house)+').');return `<p class="note">${escapeHTML(parts.join(' '))}</p>`}
{const base=checkoutForfeitNote;checkoutForfeitNote=function(room,...rest){let p=lastMonthDraft[room];if(p===undefined)p=lastMonthProrate(room);return base.call(this,room,...rest)+lastMonthNote(p)}}
// Lưu: gắn thông tin kỳ cuối vào hồ sơ trả phòng, cộng tiền hoàn thuê vào tiền hoàn cho khách
{const base=saveCheckout;saveCheckout=function(record,...rest){try{if(record&&record.status!=='Đã hoàn cọc'){const draft=lastMonthDraft[record.room];if(draft)record.lastMonth=draft;const p=record.lastMonth;if(p?.rentRefund){const expected=roundForHouse((Number(record.deposit)||0)-(record.deductions||[]).reduce((s,l)=>s+(l.amount>0?l.amount:0),0),record.house);if(Math.abs((Number(record.refund)||0)-expected)<0.005)record.refund=roundForHouse(expected+p.rentRefund,record.house)}}}catch{}return base.call(this,record,...rest)}}
// Khách xác nhận xong: kỳ cuối giảm còn số ngày ở, huỷ các kỳ sau ngày trả phòng
{const base=settleCheckoutDebts;settleCheckoutDebts=function(record,...rest){const p=record?.lastMonth;if(p){const list=readRentCharges();let changed=false;list.forEach(c=>{if(c.status!=='Chưa thu')return;if(p.futureIds.includes(c.id)){c.status='Đã huỷ';c.cancelReason='Sau ngày trả phòng';changed=true}else if(c.id===p.chargeId&&p.unused&&!p.chargePaid){const keep=roundForHouse((Number(c.originalAmount??c.amount)||0)-p.unused,record.house),paid=chargeParts(c).reduce((s,x)=>s+(Number(x.amount)||0),0);c.originalAmount=keep;c.amount=roundForHouse(keep-paid,record.house);c.title+=' · '+p.used+'/'+p.total+' ngày';if(c.amount<=0.005){c.status=paid>0?'Đã thu':'Đã huỷ';c.amount=keep}changed=true}});if(changed)localStorage.setItem('homeRentCharges',JSON.stringify(list))}const result=base.call(this,record,...rest);try{const list=readRentCharges();let fixed=false;list.forEach(c=>{if(c.room!==record.room||c.tenantKey!==record.tenantKey)return;(c.parts||[]).forEach(part=>{if(part.via==='checkout'&&record.holder&&part.by!==record.holder){part.by=record.holder;fixed=true}});if(fixed&&c.status==='Đã thu'&&(c.parts||[]).some(x=>x.via==='checkout'))c.paidBy=record.holder});if(fixed)localStorage.setItem('homeRentCharges',JSON.stringify(list))}catch{}return result}}
// Tiền thuê hoàn lại cho khách: trừ vào thu của căn
{const base=incomeEntries;incomeEntries=function(houseId,...rest){const list=base.call(this,houseId,...rest);Object.values(readCheckouts()).forEach(r=>{if(r.house!==houseId||r.status!=='Đã hoàn cọc'||!(r.lastMonth?.rentRefund>0))return;list.push({room:r.room,amount:-r.lastMonth.rentRefund,time:parseViTime(r.tenantConfirmedAt),holder:depositRemittedFlow(r.room,r.tenantKey)?ownerName():r.holder,label:r.room+' · Hoàn tiền thuê ngày chưa ở'})});return list}}

// ===== Đợt 3: (10) Bảo trì định kỳ: chủ nhà đặt lịch, đến hạn tạo việc cho quản lý, chi phí đi luồng duyệt =====
const MAINT_SOON_DAYS=3;
function readMaintPlans(){try{const v=JSON.parse(localStorage.getItem('homeMaintenancePlans')||'[]');return Array.isArray(v)?v:[]}catch{return []}}
function saveMaintPlans(list){localStorage.setItem('homeMaintenancePlans',JSON.stringify(list))}
function addMonths(time,months){const d=new Date(time),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return dayStart(d.getTime())}
function openMaintenancePlans(houseId){const overlay=document.createElement('div');overlay.className='modal-overlay';const rooms=collectRoomRecords(true).records.filter(r=>r.house===houseId).map(r=>r.code),draw=()=>{const list=readMaintPlans().filter(x=>x.house===houseId);overlay.innerHTML=`<form class="modal-sheet"><div class="modal-head">Lịch bảo trì · ${escapeHTML(readProperties().find(h=>h.id===houseId)?.name||'')}</div>${list.length?list.map(x=>`<div class="user-info-row"><span>${escapeHTML(x.title)}<br><small>${x.room?escapeHTML(x.room):'Khu chung / cả căn'} · ${x.months} tháng/lần · lần tới ${viDate(x.next)}</small></span><button type="button" class="link-btn" data-maint-del="${x.id}">Xoá</button></div>`).join(''):'<p class="note">Chưa có lịch nào.</p>'}<div class="user-section-title">Thêm lịch</div><label>Việc cần làm</label><input name="title" placeholder="Ví dụ: Vệ sinh máy lạnh"><label>Phòng</label><select name="room"><option value="">Khu chung / cả căn</option>${rooms.map(c=>`<option>${escapeHTML(c)}</option>`).join('')}</select><label>Lặp lại mỗi (tháng)</label><input name="months" type="number" min="1" max="60" value="6"><label>Lần đầu vào ngày</label><input name="first" type="date"><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-close>Đóng</button><button class="primary">Thêm lịch</button></div></form>`;const form=overlay.querySelector('form');overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());overlay.querySelectorAll('[data-maint-del]').forEach(b=>b.addEventListener('click',()=>{saveMaintPlans(readMaintPlans().filter(x=>x.id!==b.dataset.maintDel));draw()}));form.addEventListener('submit',e=>{e.preventDefault();const title=form.title.value.trim(),months=Number(form.months.value),first=form.first.value?dayStart(new Date(form.first.value+'T00:00').getTime()):0,err=form.querySelector('.user-error');if(title.length<3||!(months>=1)||!first){err.hidden=false;err.textContent='Nhập tên việc, số tháng và ngày làm lần đầu.';return}const list=readMaintPlans();list.push({id:'M'+Date.now().toString(36),house:houseId,title,room:form.room.value,months,next:first,createdAt:new Date().toLocaleString('vi-VN'),createdBy:currentActorName()});saveMaintPlans(list);draw()})};draw();appendToPhone(overlay)}
function maintDoneForm(plan){const house=plan.house,overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet"><div class="modal-head">Đã làm: ${escapeHTML(plan.title)}</div><p class="note">${plan.room?escapeHTML(plan.room):'Khu chung / cả căn'} · hạn ${viDate(plan.next)}</p><label>Chi phí (${readProperties().find(h=>h.id===house)?.currency==='VND'?'₫':'$'}, để trống nếu không tốn tiền)</label><input name="amount" type="number" min="0" step="any"><label>Ghi chú</label><input name="note" placeholder="Thợ, vật tư…"><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-close>Huỷ</button><button class="primary">Lưu</button></div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form');overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());form.addEventListener('submit',e=>{e.preventDefault();const amount=Number(form.amount.value)||0,note=form.note.value.trim(),role=document.getElementById('accountSelect').value.split('|')[0],now=new Date(),actor=currentActorName();if(amount<0)return;if(amount>0){const records=readExpenseRecords(),owner=role==='owner';records.push({id:'expense-'+Date.now()+'-maint',name:'Bảo trì định kỳ: '+plan.title+(note?' · '+note:''),amount:roundForHouse(amount,house),scope:plan.room?'Phòng riêng · '+plan.room:'Chi phí chung',room:plan.room||'',date:now.toLocaleDateString('vi-VN'),createdAt:now.toLocaleString('vi-VN'),createdBy:actor,createdByRole:role,propertyId:house,status:owner?'Đã duyệt':'Chờ duyệt',...(owner?{approvedAt:now.toLocaleString('vi-VN'),approvedBy:actor}:{}),source:'maintenance',maintId:plan.id});localStorage.setItem('homeExpenseRecords',JSON.stringify(records));try{renderExpenseRecords()}catch{}}const list=readMaintPlans(),x=list.find(i=>i.id===plan.id);if(x){x.lastDoneAt=now.toLocaleString('vi-VN');x.lastDoneBy=actor;x.next=addMonths(Math.max(x.next,dayStart()-0),x.months);saveMaintPlans(list)}if(plan.room)appendRoomHistory(plan.room,{kind:'expense',title:'Bảo trì định kỳ: '+plan.title,detail:amount>0?amountForHouse(amount,house)+(role==='owner'?'':' · chờ chủ nhà duyệt'):'Không tốn chi phí',actor,amount});overlay.remove();try{renderManagementOverview()}catch{}})}
{const base=collectWorkItems;collectWorkItems=function(...args){const items=base.apply(this,args),scope=workScope();if(!['owner','manager'].includes(scope.role))return items;const soon=dayStart()+MAINT_SOON_DAYS*DAY_MS;readMaintPlans().forEach(plan=>{if(plan.next>soon||!scope.houseOk(plan.house))return;if(plan.room&&!scope.roomOk(plan.room))return;const late=plan.next<dayStart();items.push({type:'repair',house:plan.house,room:plan.room||'',title:'Bảo trì: '+plan.title+' · '+(plan.room||'khu chung'),sub:(late?'Quá hạn từ ':'Đến hạn ')+viDate(plan.next)+' · '+plan.months+' tháng/lần'+(scope.role==='owner'?'':' · chi phí chờ chủ nhà duyệt'),time:plan.next,urgent:late,actions:[{label:'Đã làm',run:()=>maintDoneForm(plan)},{label:'Dời 7 ngày',run:()=>{const list=readMaintPlans(),x=list.find(i=>i.id===plan.id);if(x){x.next=Math.max(x.next,dayStart())+7*DAY_MS;saveMaintPlans(list)}try{renderManagementOverview()}catch{}}}],target:plan.room?{type:'room',room:plan.room}:{type:'tab',tab:'rooms'}})});return items}}

// ===== Đợt 3: (9) Mã QR chuyển khoản trên thẻ thanh toán của khách =====
function emvTLV(id,value){value=String(value);return id+String(value.length).padStart(2,'0')+value}
function crc16ccitt(text){let crc=0xFFFF;for(let i=0;i<text.length;i++){crc^=text.charCodeAt(i)<<8;for(let b=0;b<8;b++)crc=crc&0x8000?((crc<<1)^0x1021)&0xFFFF:(crc<<1)&0xFFFF}return crc.toString(16).toUpperCase().padStart(4,'0')}
function asciiText(text){return String(text||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').replace(/[^A-Za-z0-9 .\-]/g,' ').replace(/\s+/g,' ').trim()}
function vietQrPayload(bin,account,amount,note){const merchant=emvTLV('00','A000000727')+emvTLV('01',emvTLV('00',bin)+emvTLV('01',account))+emvTLV('02','QRIBFTTA');let body=emvTLV('00','01')+emvTLV('01',amount>0?'12':'11')+emvTLV('38',merchant)+emvTLV('53','704')+(amount>0?emvTLV('54',String(Math.round(amount))):'')+emvTLV('58','VN')+(note?emvTLV('62',emvTLV('08',asciiText(note).slice(0,25))):'')+'6304';return body+crc16ccitt(body)}
let qrLibPromise=null;
function loadQrLib(){if(window.QRCode)return Promise.resolve();if(!qrLibPromise)qrLibPromise=new Promise((ok,fail)=>{const sc=document.createElement('script');sc.src='https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js';sc.onload=ok;sc.onerror=()=>{qrLibPromise=null;fail()};document.head.append(sc)});return qrLibPromise}
function tenantQrInfo(){const account=document.getElementById('accountSelect').value,[role,name,room]=account.split('|');if(role!=='tenant')return null;const house=propertyIdForRoom(room),st=houseSettings(house),vnd=readProperties().find(h=>h.id===house)?.currency==='VND',open=openRentCharges(room,account),due=open[0]?.due,amount=open.filter(c=>dayStart(c.due)<=Math.max(dayStart(due),dayStart())).reduce((s,c)=>s+(Number(c.amount)||0),0),period=open[0]?.period&&/^\d{4}-\d{2}$/.test(open[0].period)?' T'+Number(open[0].period.slice(5)):'',note=room.replace('.','')+' '+name+period;if(vnd&&st.bankBin&&st.bankAccount)return {kind:'vietqr',house,room,amount,note,st};if(st.abaQr)return {kind:'aba',house,room,amount,note,st};return null}
function openTenantQr(){const info=tenantQrInfo();if(!info)return;const bank=VN_BANKS.find(([b])=>b===info.st.bankBin)?.[1]||'',overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<div class="modal-sheet"><div class="modal-head">Quét mã để chuyển khoản</div><div data-qr style="display:flex;justify-content:center;margin:6px 0 12px;min-height:200px;align-items:center">${info.kind==='aba'?`<img src="${info.st.abaQr}" alt="" style="max-width:240px;width:100%;border-radius:12px">`:'<p class="note">Đang tạo mã…</p>'}</div>${info.kind==='vietqr'?`<div class="user-info-row"><span>Ngân hàng</span><strong>${escapeHTML(bank)}</strong></div><div class="user-info-row"><span>Số tài khoản</span><strong>${escapeHTML(info.st.bankAccount)}</strong></div>${info.st.bankHolder?`<div class="user-info-row"><span>Chủ tài khoản</span><strong>${escapeHTML(info.st.bankHolder)}</strong></div>`:''}`:''}<div class="user-info-row"><span>Số tiền</span><strong>${info.amount>0?escapeHTML(amountForHouse(info.amount,info.house)):'Tự nhập'}</strong></div><div class="user-info-row"><span>Nội dung</span><strong>${escapeHTML(asciiText(info.note))}</strong></div><p class="note">${info.kind==='aba'?'Mở app ABA, quét mã rồi nhập đúng số tiền và nội dung trên.':'Mã đã có sẵn số tiền và nội dung.'} Chuyển xong bấm “Báo đã thanh toán” để quản lý xác nhận.</p><div class="modal-actions"><button type="button" data-close>Đóng</button><button type="button" class="primary" data-paid>Báo đã thanh toán</button></div></div>`;appendToPhone(overlay);overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());overlay.querySelector('[data-paid]').addEventListener('click',()=>{overlay.remove();showTenantModal('payment')});if(info.kind==='vietqr'){const box=overlay.querySelector('[data-qr]');loadQrLib().then(()=>{box.innerHTML='';new QRCode(box,{text:vietQrPayload(info.st.bankBin,info.st.bankAccount,info.amount,info.note),width:220,height:220,correctLevel:QRCode.CorrectLevel.M})}).catch(()=>{box.innerHTML='<p class="note">Không tải được mã QR (cần mạng). Chuyển khoản theo số tài khoản bên dưới.</p>'})}}
function ensureTenantQrButton(){const portal=document.getElementById('tenantPortal'),row=portal?.querySelector('.tenant-actions'),cur=portal?.querySelector('[data-tenant-qr]');const info=tenantQrInfo();if(!info){cur?.remove();return}if(!cur&&row)row.insertAdjacentHTML('beforeend','<button type="button" data-tenant-qr>Mã QR chuyển khoản</button>')}
