// ===== Thông báo trong app: quản lý / chủ nhà tạo, chủ nhà duyệt rồi mới gửi khách. Có loại "Tăng giá thuê" =====
function readNotices(){try{const v=JSON.parse(localStorage.getItem('homeNotices')||'[]');return Array.isArray(v)?v:[]}catch{return []}}
