function tenantNotices(account){const [role,,room]=String(account||'').split('|');if(role!=='tenant')return [];const house=propertyIdForRoom(room),user=readUsers().find(u=>u.key===account),since=parseViTime(getHomeContract(room)?.createdAt)||0;return readNotices().filter(n=>n.status==='Đã gửi'&&n.house===house&&(!n.rooms?.length||n.rooms.includes(room))&&(!since||parseViTime(n.sentAt)>=since-DAY_MS*45||n.kind==='rent')).sort((a,b)=>parseViTime(b.sentAt)-parseViTime(a.sentAt))}
function applyRentNotice(n){const c=getHomeContract(n.room);if(!c)return;const old=Number(c.rent)||roomLease(n.room).rent;c.prevRent=old;c.rent=Number(n.newRent);c.rentFrom=dayStart(n.rentFrom);c.rentNoticeId=n.id;saveHomeContract(n.room,c);appendRoomHistory(n.room,{kind:'contract',title:'Tăng giá thuê từ '+viDate(n.rentFrom),detail:amountForHouse(old,n.house)+' → '+amountForHouse(n.newRent,n.house)+' · đã gửi thông báo cho khách',actor:currentActorName()})}
function sendNotice(id){const list=readNotices(),n=list.find(x=>x.id===id);if(!n||n.status==='Đã gửi')return;n.status='Đã gửi';n.sentAt=new Date().toLocaleString('vi-VN');n.approvedBy=currentActorName();saveNotices(list);if(n.kind==='rent')applyRentNotice(n);try{renderManagementOverview()}catch{}}
function rejectNotice(id,reason){if(reason===undefined){const n0=readNotices().find(x=>x.id===id),overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet"><div class="modal-head">Không duyệt thông báo</div><p class="note">${escapeHTML(n0?.title||'')}</p><label>Lý do (quản lý sẽ thấy)</label><textarea name="reason" rows="3"></textarea><div class="modal-actions"><button type="button" data-close>Huỷ</button><button class="primary">Không duyệt</button></div></form>`;appendToPhone(overlay);overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());overlay.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const t=overlay.querySelector('[name=reason]').value;overlay.remove();rejectNotice(id,t)});return}const list=readNotices(),n=list.find(x=>x.id===id);if(!n)return;n.status='Từ chối';n.rejectReason=String(reason).trim()||'Không ghi lý do';n.rejectedAt=new Date().toLocaleString('vi-VN');saveNotices(list);try{renderManagementOverview()}catch{}}
function openNoticeForm(){const scope=workScope(),house=readProperty().id||'HOME-001',home=readProperties().find(h=>h.id===house)||{},rooms=collectRoomRecords(true).records.filter(r=>r.house===house&&r.status==='Đang thuê'&&scope.roomOk(r.code)).map(r=>r.code),money=home.currency==='VND'?'₫':'$',overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet"><div class="modal-head">Tạo thông báo · ${escapeHTML(home.name||'')}</div><label>Loại</label><select name="kind"><option value="general">Thông báo chung</option><option value="rent">Tăng giá thuê một phòng</option></select><div data-general><label>Gửi tới</label><select name="target"><option value="">${scope.role==='owner'?'Tất cả khách trong căn':'Tất cả khách các phòng em phụ trách'}</option>${rooms.map(r=>`<option>${escapeHTML(r)}</option>`).join('')}</select><label>Tiêu đề</label><input name="title" placeholder="Ví dụ: Cắt nước ngày 05/11"><label>Nội dung</label><textarea name="body" rows="4"></textarea></div><div data-rent hidden><label>Phòng</label><select name="room">${rooms.map(r=>`<option>${escapeHTML(r)}</option>`).join('')}</select><p class="note" data-rent-now></p><label>Giá thuê mới (${money})</label><input name="newRent" type="number" min="0" step="any"><label>Áp dụng từ ngày</label><input name="rentFrom" type="date"><label>Lời nhắn thêm (không bắt buộc)</label><textarea name="rentNote" rows="2"></textarea></div><p class="note">${scope.role==='owner'?'Chủ nhà tạo thì gửi ngay.':'Thông báo sẽ chờ chủ nhà duyệt rồi mới gửi tới khách.'}</p><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-close>Huỷ</button><button class="primary">${scope.role==='owner'?'Gửi':'Gửi chủ nhà duyệt'}</button></div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form'),err=form.querySelector('.user-error'),d=new Date(Date.now()+30*DAY_MS),sync=()=>{const rent=form.kind.value==='rent';form.querySelector('[data-general]').hidden=rent;form.querySelector('[data-rent]').hidden=!rent;const r=form.room.value;form.querySelector('[data-rent-now]').textContent=r?'Giá hiện tại: '+amountForHouse(roomLease(r).rent,house):''};form.rentFrom.value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');form.kind.addEventListener('change',sync);form.room.addEventListener('change',sync);sync();overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());form.addEventListener('submit',e=>{e.preventDefault();const show=t=>{err.hidden=false;err.textContent=t},now=new Date().toLocaleString('vi-VN'),n={id:'N'+Date.now().toString(36),house,kind:form.kind.value,createdBy:currentActorName(),createdByRole:scope.role,createdAt:now,status:'Chờ duyệt',readBy:{}};if(n.kind==='rent'){const room=form.room.value,rent=Number(form.newRent.value),from=form.rentFrom.value?dayStart(new Date(form.rentFrom.value+'T00:00').getTime()):0,old=roomLease(room).rent;if(!room)return show('Chọn phòng.');if(!(rent>0))return show('Nhập giá thuê mới.');if(rent===old)return show('Giá mới bằng giá hiện tại.');if(!from||from<dayStart())return show('Chọn ngày áp dụng từ hôm nay trở đi.');if(from<dayStart()+30*DAY_MS&&!form.dataset.shortOk){appConfirm('Ngày áp dụng chưa tới 30 ngày','Khách có ít thời gian chuẩn bị. Vẫn gửi?','Vẫn gửi',()=>{form.dataset.shortOk='1';form.requestSubmit()});return}const tenant=roomTenantUser(room)?.name||'';Object.assign(n,{room,rooms:[room],newRent:roundForHouse(rent,house),oldRent:old,rentFrom:from,title:(rent>old?'Điều chỉnh tăng':'Điều chỉnh')+' giá thuê phòng '+room,body:'Gửi '+(tenant||'anh/chị')+': từ ngày '+viDate(from)+' giá thuê phòng '+room+' là '+amountForHouse(rent,house)+' / tháng (hiện tại '+amountForHouse(old,house)+').'+(form.rentNote.value.trim()?'\n'+form.rentNote.value.trim():'')})}else{const title=form.title.value.trim(),body=form.body.value.trim();if(title.length<3||body.length<3)return show('Nhập tiêu đề và nội dung.');const target=form.target.value;Object.assign(n,{title,body,rooms:target?[target]:(scope.role==='owner'?[]:rooms)})}const list=readNotices();list.push(n);saveNotices(list);overlay.remove();if(scope.role==='owner')sendNotice(n.id);else try{renderManagementOverview()}catch{}openNoticeList()})}
function noticeRow(n,opts={}){const tag=n.status==='Đã gửi'?'Đã gửi '+(n.sentAt||''):n.status==='Từ chối'?'Không duyệt: '+(n.rejectReason||''):'Chờ chủ nhà duyệt';return `<div class="notice-item${opts.unread?' unread':''}" ${opts.read?`data-notice-read="${n.id}"`:''}><h5>${escapeHTML(n.title)}</h5><p>${escapeHTML(n.body)}</p><small>${opts.tenant?escapeHTML(n.sentAt||''):escapeHTML(noticeAudience(n))+' · '+escapeHTML(n.createdBy)+' · '+escapeHTML(tag)}</small></div>`}
function openNoticeList(){document.querySelectorAll('.modal-overlay[data-notice-list]').forEach(o=>o.remove());const scope=workScope(),house=readProperty().id||'HOME-001',list=readNotices().filter(n=>n.house===house&&(scope.role==='owner'||n.createdBy===scope.name||(n.status==='Đã gửi'&&(!n.rooms?.length||n.rooms.some(r=>scope.roomOk(r)))))).sort((a,b)=>parseViTime(b.createdAt)-parseViTime(a.createdAt)),overlay=document.createElement('div');overlay.className='modal-overlay';overlay.dataset.noticeList='1';overlay.innerHTML=`<div class="modal-sheet"><div class="modal-head">Thông báo gửi khách</div>${list.length?list.slice(0,20).map(n=>noticeRow(n)).join(''):'<p class="note">Chưa có thông báo nào.</p>'}<div class="modal-actions"><button type="button" data-close>Đóng</button><button type="button" class="primary" data-new>＋ Tạo thông báo</button></div></div>`;appendToPhone(overlay);overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());overlay.querySelector('[data-new]').addEventListener('click',()=>{overlay.remove();openNoticeForm()})}
