const APP_FEEDBACK_ROLE={manager:'quan_ly',tenant:'khach'},APP_FEEDBACK_ROLE_NAME={quan_ly:'Quản lý',khach:'Khách thuê'};
function readLocalAppFeedback(){try{const list=JSON.parse(localStorage.getItem('homeAppFeedback')||'[]');return Array.isArray(list)?list:[]}catch{return[]}}
