const ACCOUNT_KEEP_DAYS=30,ID_PHOTO_KEEP_DAYS=365;
function checkoutDebtOpen(rec){return readRentCharges().some(c=>c.tenantKey===rec.tenantKey&&c.status==='Chưa thu')}
function autoCloseTenantAccounts(){const all=readCheckouts();let usersChanged=false,recChanged=false;const users=readUsers();Object.values(all).forEach(rec=>{if(rec.status!=='Đã hoàn cọc')return;const done=parseViTime(rec.tenantConfirmedAt);if(!done)return;if(!rec.accountDeletedAt&&Date.now()-done>=ACCOUNT_KEEP_DAYS*DAY_MS&&!checkoutDebtOpen(rec)){const u=users.find(x=>x.key===rec.tenantKey);if(u&&u.status!=='Đã xoá'){u.status='Đã xoá';u.deletedAt=new Date().toLocaleString('vi-VN');logUserChange(u,'Tự xoá '+ACCOUNT_KEEP_DAYS+' ngày sau khi trả phòng');usersChanged=true}rec.accountDeletedAt=new Date().toLocaleString('vi-VN');rec.accountDeletedBy='Tự động';recChanged=true}if(Date.now()-done>=ID_PHOTO_KEEP_DAYS*DAY_MS&&!rec.idPhotosPurgedAt&&(rec.contract?.idPhotos?.length||rec.contract?.extraPeople?.some(p=>p.photos?.length))){if(rec.contract.idPhotos)rec.contract.idPhotos=[];(rec.contract.extraPeople||[]).forEach(p=>p.photos=[]);rec.idPhotosPurgedAt=new Date().toLocaleString('vi-VN');recChanged=true}});if(usersChanged)saveUsers(users);if(recChanged)localStorage.setItem('homeCheckouts',JSON.stringify(all));if(usersChanged)try{refreshUserAccounts()}catch{}}
setTimeout(()=>{try{autoCloseTenantAccounts()}catch{}},0);
// Việc "Xoá tài khoản khách" không cần nữa: app tự xoá khi đủ 30 ngày và hết nợ
{const base=collectWorkItems;collectWorkItems=function(...args){const items=base.apply(this,args),recs=readCheckouts();return items.filter(it=>!/^Xoá tài khoản khách /.test(it.title||''))}}
// Khách đã chuyển phòng: màn hình lịch sử ghép thêm các việc ở phòng trước (tới lúc chuyển)
function priorRoomEvents(room,name,depth=0){const user=readUsers().find(u=>u.key==='tenant|'+name+'|'+room);if(!user?.movedFrom||depth>3)return [];const from=user.movedFrom,until=parseViTime(getHomeContract(room)?.transferredAt)||Date.now(),saved=(()=>{try{return JSON.parse(localStorage.getItem('homeTenantEvents')||'{}')[from]||[]}catch{return []}})(),profile=tenantProfiles[from]||{},list=[...(profile.activities||[]).map(i=>({date:String(i.date||''),title:String(i.title||''),detail:String(i.detail||''),status:i.status?String(i.status):''})),...(profile.payments||[]).map(i=>({date:i.date,title:i.title,detail:i.amount+' · '+i.status})),...saved.map(i=>({date:String(i.date||''),title:String(i.title||'Hoạt động'),detail:String(i.detail||''),status:i.status?String(i.status):'',ts:(/^\d{13}/.test(String(i.id||''))?Number(String(i.id).slice(0,13)):0)||Math.min(...[i.createdAt,i.at,i.time].map(v=>parseViTime(v)||Infinity))||0}))].filter(e=>!(Number.isFinite(e.ts)&&e.ts>until+1000)).map(e=>({...e,title:e.title+' ('+from+')'}));const own=tenantOwnHistory(list,from,name,null);return [...priorRoomEvents(from,name,depth+1),...own]}
// Chủ nhà lấy lại phòng: khách không tự huỷ được; thẻ của khách ghi rõ
{const base=cancelMoveOutRequest;cancelMoveOutRequest=function(...args){const [,,room]=document.getElementById('accountSelect').value.split('|');if(moveOutRequest(room)?.byOwner)return;return base.apply(this,args)}}
{const base=renderTenantConfirmations;renderTenantConfirmations=function(...args){const result=base.apply(this,args);try{const [,,room]=document.getElementById('accountSelect').value.split('|'),req=moveOutRequest(room);if(req?.byOwner){document.querySelectorAll('#tenantConfirmBox .confirm-card').forEach(card=>{const t=card.querySelector('.tenant-title');if(t&&/^Đã báo trả phòng/.test(t.textContent)){t.textContent='Chủ nhà lấy lại phòng · '+room;card.querySelectorAll('button').forEach(b=>{if(/Huỷ/.test(b.textContent))b.remove()});if(!card.querySelector('[data-reclaim-note]'))card.insertAdjacentHTML('beforeend','<p class="note" data-reclaim-note>Anh/chị được hoàn đủ tiền cọc và tiền thuê những ngày chưa ở.</p>')}})}}catch{}return result}}
