function readGuestStays(){try{const v=JSON.parse(localStorage.getItem('homeGuestStays')||'[]');return Array.isArray(v)?v:[]}catch{return []}}
function openGuestForm(){const [role,name,room]=document.getElementById('accountSelect').value.split('|');if(role!=='tenant')return;const d=new Date(),iso=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'),overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet"><div class="modal-head">Báo có người ở lại · ${escapeHTML(room)}</div><label>Họ tên người ở lại</label><input name="guest"><label>Từ ngày</label><input name="from" type="date" value="${iso}"><label>Số đêm</label><input name="nights" type="number" min="1" value="1"><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-close>Huỷ</button><button class="primary">Gửi quản lý</button></div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form');overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());form.addEventListener('submit',e=>{e.preventDefault();const guest=form.guest.value.trim(),nights=Math.floor(Number(form.nights.value)),err=form.querySelector('.user-error');if(guest.length<2||!(nights>=1)||!form.from.value){err.hidden=false;err.textContent='Nhập tên, ngày và số đêm.';return}const from=viDate(new Date(form.from.value+'T00:00').getTime()),list=readGuestStays();list.push({id:'G'+Date.now().toString(36),room,house:propertyIdForRoom(room),tenantKey:document.getElementById('accountSelect').value,tenantName:name,guest,from,nights,at:new Date().toLocaleString('vi-VN')});localStorage.setItem('homeGuestStays',JSON.stringify(list));appendRoomHistory(room,{kind:'room',title:'Báo có người ở lại: '+guest,detail:'Từ '+from+' · '+nights+' đêm',tenantName:name});overlay.remove();refreshTenantScreen('Đã báo quản lý có người ở lại.')})}
