{const base=renderTenantConfirmations;renderTenantConfirmations=function(...args){const result=base.apply(this,args);try{renderTenantLeaseChoice()}catch{}try{const portal=document.getElementById('tenantPortal'),row=[...(portal?.querySelectorAll('.tenant-actions')||[])].find(r=>r.querySelector('[data-complaint-open]'))||[...(portal?.querySelectorAll('.tenant-actions')||[])].pop();if(document.getElementById('accountSelect').value.startsWith('tenant|')&&row&&!portal.querySelector('[data-guest-open]'))row.insertAdjacentHTML('beforeend','<button type="button" data-guest-open>Báo có người ở lại</button>')}catch{}return result}}
