function openLostKeyForm(room){const user=roomTenantUser(room);if(!user)return;const house=propertyIdForRoom(room),overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<form class="modal-sheet"><div class="modal-head">Khách mất đồ · ${escapeHTML(room)}</div><div class="user-info-row"><span>Khách thuê</span><strong>${escapeHTML(user.name)}</strong></div><label>Món bị mất</label><select name="item"><option>Chìa khoá</option><option>Thẻ từ</option><option>Remote cổng / máy lạnh</option><option>Khác</option></select><label>Giá thực tế đã mua / làm lại (${readProperties().find(h=>h.id===house)?.currency==='VND'?'₫':'$'})</label><input name="cost" type="number" min="0" step="any"><label>Ảnh hoá đơn (bắt buộc)</label><input name="receipt" type="file" accept="image/*"><p class="note">Ghi thành khoản chi của căn (đi luồng duyệt như thường) và khoản khách phải trả cùng số tiền.</p><p class="user-error" hidden></p><div class="modal-actions"><button type="button" data-close>Huỷ</button><button class="primary">Lưu</button></div></form>`;appendToPhone(overlay);const form=overlay.querySelector('form'),err=form.querySelector('.user-error');let receipt='',pending=false;form.receipt.addEventListener('change',async()=>{pending=true;try{receipt=await compressInventoryPhoto(form.receipt.files[0])}catch{receipt=''}pending=false});overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());form.addEventListener('submit',e=>{e.preventDefault();const cost=Number(form.cost.value),show=t=>{err.hidden=false;err.textContent=t};if(pending)return show('Đang xử lý ảnh, bấm lại sau giây lát.');if(!(cost>0))return show('Nhập giá thực tế.');if(!receipt)return show('Thêm ảnh hoá đơn.');const role=document.getElementById('accountSelect').value.split('|')[0],actor=currentActorName(),now=new Date(),id='expense-'+Date.now()+'-lost',records=readExpenseRecords(),amount=roundForHouse(cost,house),owner=role==='owner';records.push({id,name:'Làm lại '+form.item.value.toLowerCase()+' cho khách '+user.name,amount,scope:'Phòng riêng · '+room,room,date:now.toLocaleDateString('vi-VN'),createdAt:now.toLocaleString('vi-VN'),createdBy:actor,createdByRole:role,propertyId:house,status:owner?'Đã duyệt':'Chờ duyệt',...(owner?{approvedAt:now.toLocaleString('vi-VN'),approvedBy:actor}:{}),receipt,source:'lost-key'});localStorage.setItem('homeExpenseRecords',JSON.stringify(records));addTenantDebt(room,user.key,user.name,'Làm lại '+form.item.value.toLowerCase()+' bị mất',amount,'lost-'+Date.now(),actor);appendRoomHistory(room,{kind:'charge',title:'Khách mất '+form.item.value.toLowerCase()+': thu '+amountForHouse(amount,house),detail:'Theo giá thực tế · '+actor,actor,tenantName:user.name,amount});overlay.remove();try{renderExpenseRecords()}catch{}try{renderManagementOverview()}catch{}})}
new MutationObserver(()=>{document.querySelectorAll('.phone .rd-sheet').forEach(sheet=>{if(sheet.querySelector('[data-lost-key]'))return;const code=(sheet.querySelector('.modal-head')?.textContent.match(/P\.\d+/)||[])[0];if(!code||!roomTenantUser(code)||!roomRented(code))return;if(!['owner','manager'].includes(document.getElementById('accountSelect').value.split('|')[0])||!canManageCheckout(code))return;const actions=sheet.querySelector('.modal-actions');(actions||sheet).insertAdjacentHTML(actions?'beforebegin':'beforeend',`<button type="button" class="link-btn" data-lost-key="${escapeHTML(code)}">Khách mất chìa khoá / thẻ</button>`)})}).observe(document.querySelector('.phone')||document.body,{childList:true,subtree:true});
document.addEventListener('click',e=>{const b=e.target.closest('[data-lost-key]');if(b)openLostKeyForm(b.dataset.lostKey)});
// Việc: khách báo người ở lại (quản lý biết), quản lý giữ tiền quá hạn mức (nộp sớm)
{const base=collectWorkItems;collectWorkItems=function(...args){const items=base.apply(this,args),scope=workScope();if(!['owner','manager'].includes(scope.role))return items;readGuestStays().forEach(g=>{if(g.seenAt||!scope.houseOk(g.house)||!scope.roomOk(g.room))return;items.push({type:'room',house:g.house,room:g.room,title:g.room+': '+g.tenantName+' báo có người ở lại',sub:g.guest+' · từ '+g.from+' · '+g.nights+' đêm',time:parseViTime(g.at),actions:[{label:'Đã biết',run:()=>{const l=readGuestStays(),x=l.find(i=>i.id===g.id);if(x){x.seenAt=new Date().toLocaleString('vi-VN');x.seenBy=currentActorName();localStorage.setItem('homeGuestStays',JSON.stringify(l))}try{renderManagementOverview()}catch{}}}],target:{type:'room',room:g.room}})});readProperties().forEach(home=>{const limit=Number(houseSettings(home.id).cashLimit)||0;if(!limit||!scope.houseOk(home.id))return;(custodySummary(home.id)||[]).forEach(entry=>{const held=Math.max(0,Number(entry.ownerMoney)||0);if(held<=limit||!entry.name||entry.name===ownerName())return;if(scope.role==='manager'&&entry.name!==scope.name)return;items.push({type:'payment',house:home.id,room:'',urgent:true,title:(scope.role==='manager'?'Anh/chị':entry.name)+' đang giữ '+amountForHouse(held,home.id)+' tiền của chủ nhà',sub:'Quá mức '+amountForHouse(limit,home.id)+' · '+(scope.role==='manager'?'nộp sớm cho chủ nhà, không chờ chốt tháng':'nhắc quản lý nộp sớm'),time:Date.now(),actions:[],target:{type:'settle',month:monthKeyOf(Date.now())}})})});return items}}
// Đợt 5 sửa theo tester
function roomRented(room){try{const card=cardForRoom(room);if(card)return getRoomCardRecord(card).status==='Đang thuê';const st=JSON.parse(localStorage.getItem('homeRoomStatuses')||'{}')[room];if(st)return st.status==='Đang thuê';return !!collectRoomRecords(true).records.find(r=>r.code===room&&r.status==='Đang thuê')}catch{return true}}
function appToast(text){document.querySelectorAll('.app-toast').forEach(t=>t.remove());const t=document.createElement('div');t.className='app-toast';t.textContent=text;(document.querySelector('.phone')||document.body).append(t);setTimeout(()=>t.remove(),2600)}
function refreshTenantScreen(text){const a=document.getElementById('accountSelect').value;try{setAccount(a)}catch{try{renderTenantConfirmations()}catch{}}if(text)appToast(text)}
// Chủ nhà mở cài đặt căn đang có từ form "Thêm căn"
{const base=openPropertyForm;openPropertyForm=function(startCreating=true,...rest){const r=base.call(this,startCreating,...rest);try{if(startCreating!==false&&document.getElementById('accountSelect').value.startsWith('owner|')&&readProperties().length){const ov=[...document.querySelectorAll('.modal-overlay')].pop(),head=ov?.querySelector('.modal-head');if(head&&!ov.querySelector('[data-house-edit]')){head.insertAdjacentHTML('afterend','<button type="button" class="link-btn" data-house-edit style="display:block;margin:0 0 10px">Sửa cài đặt căn đang có (ngân hàng, thưởng, hạn mức tiền, phụ phí…) ›</button>');ov.querySelector('[data-house-edit]').addEventListener('click',()=>{ov.remove();openPropertyForm(false)})}}}catch{}return r}}
// Từ chối gia hạn do khách đề nghị: lý do gửi cho khách
{const base=rejectRenewal;rejectRenewal=function(room,...rest){const r=base.call(this,room,...rest);try{const c=readHomeContracts()[room];if(c?.renewal?.byTenant){const ov=[...document.querySelectorAll('.modal-overlay')].pop();ov?.querySelectorAll('label').forEach(l=>{l.textContent=l.textContent.replace('(quản lý sẽ thấy)','(khách sẽ thấy)')})}}catch{}return r}}
// ===== Việc màu đỏ luôn lên đầu (đặt cuối cùng để áp cho mọi loại việc thêm sau) =====
{const base=collectWorkItems;collectWorkItems=function(...args){const items=base.apply(this,args);return items.map((item,i)=>[item,i]).sort((a,b)=>((b[0].urgent?1:0)-(a[0].urgent?1:0))||a[1]-b[1]).map(x=>x[0])}}

// ===== Khách mới chỉ thấy lịch sử từ khi mình thuê, không thấy của khách cũ cùng phòng =====
function tenantOwnHistory(events,room,name,contract){const me=String(name||'').trim(),dateOf=text=>{const m=String(text||'').match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);return m?new Date(+m[3],m[2]-1,+m[1]).getTime():0},prev=readCheckouts()[room],prevName=String(prev?.tenantName||'').trim(),prevAt=prev?.tenantConfirmedAt?parseViTime(prev.tenantConfirmedAt):0;let start=0,end=0;if(contract&&String(contract.tenantName||'').trim()===me&&contract.createdAt)start=parseViTime(contract.createdAt);if(prev&&prevName!==me&&prevAt)start=prevAt;if(prev&&prevName===me&&prevAt)end=prevAt;const others=[...new Set([prevName,...readHolds().filter(h=>h.room===room).map(h=>h.name)].filter(n=>n&&String(n).trim()!==me))];return events.filter(e=>{const ts=Number.isFinite(Number(e.ts))?Number(e.ts):0,day=dateOf(e.date),own=((e.title||'')+' '+(e.detail||''));if(me&&/giữ chỗ/i.test(own)&&own.includes(me))return true;if(start){if(ts&&ts<start-1000)return false;if(!ts&&day&&day<dayStart(start))return false}if(end){if(ts&&ts>end+1000)return false;if(!ts&&day&&day>dayStart(end))return false}const text=(e.title||'')+' '+(e.detail||'');if(others.some(n=>text.includes(n)))return false;if(/giữ chỗ/i.test(text)&&!text.includes(me))return false;if(prev&&prevName!==me&&/trả phòng|nhận lại tiền cọc/i.test(e.title||'')&&!(ts&&ts>prevAt+1000))return false;return true})}
